('6140c188-46ad-5f1b-add3-af65a438cece','d27a813b-1093-59da-b8de-c1cbc320b648',3,null,null,'spoken & written','done or said without intending to harm or offend anyone',null,null,'بدون قصد آسیب رساندن یا توهین به کسی انجام شود یا گفته شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was startled by their angry reaction to his innocent remark.","translation":"او از واکنش خشمگینانه آنها نسبت به اظهارات معصومانه او مبهوت شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001413869.mp3"}]'::jsonb,1),
('9508c212-f392-5564-9f87-858b5fa15410','d27a813b-1093-59da-b8de-c1cbc320b648',4,null,null,'spoken & written','not having much experience of the bad things in the world, so that you are easily deceived',null,null,'نداشتن تجربه زیادی از چیزهای بد دنیا، به طوری که به راحتی فریب می خورید',array['naive']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I was thirteen years old and very innocent.","translation":"من سیزده ساله بودم و بسیار بی گناه.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001413874.mp3"}]'::jsonb,1),
