('7d208a7c-a7f8-5953-8562-9fd761c5c717','72afdf71-11bf-5735-b2e2-e1af930917d5',2,null,null,'spoken & written','an example of a particular kind of situation','[ countable ]',null,'نمونه ای از یک نوع موقعیت خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They came across many instances of discrimination.","translation":"آنها با موارد زیادی از تبعیض مواجه شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001416901.mp3"},{"sentence":"instances where safety regulations have been breached","translation":"مواردی که مقررات ایمنی نقض شده است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718993.mp3"},{"sentence":"In this instance I think she was mistaken.","translation":"در این مورد فکر می کنم او اشتباه کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001416904.mp3"}]'::jsonb,3),
('01a2314f-5d95-5db3-a029-1371d8e5d0c9','72afdf71-11bf-5735-b2e2-e1af930917d5',3,null,null,'spoken & written',null,null,'in the first instance','نمونه، مصداق؛ مورد (خاص)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
