('d11a1f23-77c8-5452-b43c-4e9025d613f3','fbdac46c-5bf9-5b0e-b884-6f9931d5da00',3,null,null,'spoken & written','to try to persuade someone to buy, do, or eat something',null,null,'تلاش برای متقاعد کردن کسی برای خرید، انجام یا خوردن چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The salesman tried to interest me in the higher-priced model.","translation":"فروشنده سعی کرد من را به مدلی با قیمت بالاتر علاقه مند کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721560.mp3"}]'::jsonb,1),
('2cbd7e17-5223-5891-be52-ec4c59a3b0c8','c405b39a-689e-57e5-ad2f-cca5b24e2c55',1,null,null,'spoken & written','within a particular country',null,null,'داخلی، درون‌کشوری؛ داخلی (سیاست)',array['domestic']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We have no interest in interfering in the internal affairs of other countries.","translation":"ما هیچ علاقه ای به دخالت در امور داخلی کشورهای دیگر نداریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721683.mp3"},{"sentence":"the threat to internal security","translation":"تهدید امنیت داخلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001420714.mp3"},{"sentence":"internal markets","translation":"بازارهای داخلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721689.mp3"}]'::jsonb,3),
('36632b72-2f34-5a8c-932d-1cd7dbcf13b9','c405b39a-689e-57e5-ad2f-cca5b24e2c55',2,null,null,'spoken & written','within a company or organization rather than outside it',null,null,'در داخل یک شرکت یا سازمان به جای خارج از آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There’s to be an internal inquiry into the whole affair.","translation":"باید یک تحقیق داخلی در مورد کل ماجرا انجام شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001420707.mp3"},{"sentence":"the internal mail","translation":"پست داخلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001420708.mp3"}]'::jsonb,2),
