('c0c2c1f1-3628-5a21-8b7b-70dd88419f3e','c405b39a-689e-57e5-ad2f-cca5b24e2c55',4,null,null,'spoken & written','inside something rather than outside',null,null,'درون چیزی به جای بیرون','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They’ve knocked down a couple of internal walls.","translation":"آنها چند دیوار داخلی را خراب کرده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001420696.mp3"}]'::jsonb,1),
