('df926c3e-ce39-59ce-b6f4-cf207ceddf11','3125c7e5-bba2-591f-9ef3-280880a08d5d',3,null,null,'spoken & written','a place away from a film studio where scenes are filmed','[ countable, uncountable ]',null,'مکانی دور از استودیوی فیلمبرداری که در آن صحنه فیلمبرداری می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It was hard to find a suitable location for the desert scenes.","translation":"پیدا کردن مکان مناسب برای صحنه های کویر سخت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001508818.mp3"},{"sentence":"Most of the movie was shot on location in Africa.","translation":"بیشتر فیلم در لوکیشنی در آفریقا فیلمبرداری شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001508821.mp3"}]'::jsonb,2),
('62a83e3b-246a-5ab4-aff7-5da23730d73a','3125c7e5-bba2-591f-9ef3-280880a08d5d',4,null,null,'spoken & written','the act of finding the position of something','[ uncountable ]',null,'عمل یافتن موقعیت چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The main problem for engineers was the location of underground rivers in the area.","translation":"مشکل اصلی مهندسان محل رودخانه های زیرزمینی در این منطقه بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001508826.mp3"}]'::jsonb,1),
('feccb403-ad01-5729-bfd3-7866db694caa','0511728a-5ec3-55c6-b6ca-4b3142c82012',1,null,null,'spoken & written','a large thin book with a paper cover that contains news stories, articles , photographs etc, and is sold weekly or monthly',null,null,'مجله، ماهنامه؛ انبار (سلاح)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a glossy fashion magazine","translation":"یک مجله مد براق","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000172091.mp3"},{"sentence":"She’s the editor of a popular women’s magazine.","translation":"او سردبیر یک مجله محبوب زنانه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714154.mp3"},{"sentence":"a magazine article","translation":"یک مقاله مجله","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714153.mp3"},{"sentence":"She glanced over the magazine racks.","translation":"نگاهی به قفسه های مجله انداخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752637.mp3"}]'::jsonb,4),
