('96a0f93b-9f30-5715-baa8-fb80d9168c9c','f0906f68-8d63-5b50-b5a7-232cbdba7d80',1,'make something continue','کاری کن که ادامه پیدا کنه','spoken & written','to make something continue in the same way or at the same standard as before',null,null,'حفظ کردن، نگه داشتن؛ نگهداری کردن (ساختمان)؛ ادعای (نظر)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Careers Officers maintain contact with young people when they have left school.","translation":"افسران شغلی پس از ترک تحصیل با جوانان ارتباط برقرار می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000996.mp3"},{"sentence":"Britain wants to maintain its position as a world power.","translation":"بریتانیا می خواهد جایگاه خود را به عنوان یک قدرت جهانی حفظ کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000173684.mp3"},{"sentence":"A lot depends on building and maintaining a good relationship with your customers.","translation":"خیلی به ایجاد و حفظ رابطه خوب با مشتریان شما بستگی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000173685.mp3"},{"sentence":"The hotel prides itself on maintaining high standards.","translation":"این هتل به حفظ استانداردهای بالا افتخار می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001534109.mp3"},{"sentence":"How can we maintain control of spending?","translation":"چگونه می توانیم کنترل هزینه ها را حفظ کنیم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752769.mp3"}]'::jsonb,5),
('a71849ed-c2ac-5b16-ae8c-e61bc64b309c','f0906f68-8d63-5b50-b5a7-232cbdba7d80',2,'level/rate','سطح/نرخ','spoken & written','to make a level or rate of activity , movement etc stay the same',null,null,'تا سطح یا میزان فعالیت، حرکت و غیره ثابت بماند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It is important to maintain a constant temperature inside the greenhouse.","translation":"حفظ دمای ثابت در داخل گلخانه مهم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000173690.mp3"},{"sentence":"This is the most efficient way to build up and maintain a reasonable level of physical fitness.","translation":"این کارآمدترین راه برای ایجاد و حفظ سطح مناسبی از آمادگی جسمانی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001534121.mp3"}]'::jsonb,2),
('c3168d0e-a6cf-51bd-b10c-84ee88e1e782','f0906f68-8d63-5b50-b5a7-232cbdba7d80',3,'say','بگو','spoken & written','to strongly express your belief that something is true',null,null,'به شدت اعتقاد خود را به درستی چیزی ابراز کنید',array['claim']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Critics maintain that these reforms will lead to a decline in educational standards.","translation":"منتقدان معتقدند که این اصلاحات منجر به کاهش استانداردهای آموزشی خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000173707.mp3"},{"sentence":"He maintained his innocence and said the allegations were ‘ridiculous’.","translation":"او بر بی گناهی خود تاکید کرد و گفت که این اتهامات \"مضحک\" هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752775.mp3"}]'::jsonb,2),
('dbf6dd02-7fd8-550e-8a8b-2ed1f1c10c10','f0906f68-8d63-5b50-b5a7-232cbdba7d80',4,'look after something','مراقب چیزی','spoken & written','to keep a machine , building etc in good condition by checking and repairing it regularly',null,null,'برای نگهداری یک ماشین، ساختمان و غیره با بررسی و تعمیر منظم آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The report found that safety equipment had been very poorly maintained.","translation":"این گزارش نشان داد که تجهیزات ایمنی بسیار ضعیف نگهداری شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000173695.mp3"},{"sentence":"The company is responsible for maintaining public telephone boxes.","translation":"این شرکت وظیفه نگهداری از صندوق های تلفن عمومی را بر عهده دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001534128.mp3"}]'::jsonb,2),
('77b20243-0f9a-5555-ba24-ef1c9eb90c75','f0906f68-8d63-5b50-b5a7-232cbdba7d80',5,'provide money/food','پول/غذا فراهم کنید','spoken & written','to provide someone with the things they need, such as money or food',null,null,'برای فراهم کردن وسایل مورد نیاز کسی، مانند پول یا غذا',array['provide for']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"How can you maintain a family on $900 a month?","translation":"چگونه می توانید خانواده خود را با 900 دلار در ماه نگهداری کنید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000173715.mp3"}]'::jsonb,1),
('74a0175c-08eb-59ff-b5a7-0a4bf5be8790','5d13c91a-7fb0-52c6-b291-ed03d607d888',1,'most people or things','اکثر افراد یا چیزها','spoken & written','most of the people or things in a group','[ singular ]','silent majority','اکثریت، بیشتر (گروه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The majority of workers find it quite hard to live on the amount of money they earn.","translation":"برای اکثریت کارگران، زندگی با مقدار پولی که به دست می آورند بسیار سخت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000997.mp3"},{"sentence":"In the vast majority of cases the disease is fatal.","translation":"در اکثریت قریب به اتفاق موارد این بیماری کشنده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000175035.mp3"},{"sentence":"In this city, Muslims are in the majority.","translation":"در این شهر مسلمانان اکثریت هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001566930.mp3"},{"sentence":"The majority of patients are women.","translation":"اکثر بیماران زن هستند.","audio_url":null},{"sentence":"He sees several patients a day. The majority are women.","translation":"او روزی چندین بیمار را می بیند. اکثریت زنان هستند.","audio_url":null},{"sentence":"The majority is unwilling to listen to the views of the minority.","translation":"اکثریت حاضر نیستند به نظرات اقلیت گوش دهند.","audio_url":null}]'::jsonb,6),
('8cfb23cb-ba35-5f1c-a7ce-3f5754a0d1bf','5d13c91a-7fb0-52c6-b291-ed03d607d888',2,'most votes','بیشترین رای','spoken & written','if one person or group wins a majority in an election , they win more votes than other people or groups','[ countable ]',null,'اگر یک فرد یا گروه اکثریت را در انتخابات به دست آورد، آرای بیشتری را نسبت به افراد یا گروه های دیگر کسب می کند','{}'::text[],'{}'::text[],array['have/hold a majority The Democratic party has a majority in the Senate.','win a majority The Conservative Party won a large majority.','secure a majority (= win a majority ) They failed to secure a majority.','get/gain/receive a majority If no one gets an overall majority, the vote is repeated.','command a majority (= have a majority ) They were one seat short of being able to command a majority in parliament.','increase a majority (= get more votes than you had before ) Labour increased its majority in the area.','lose a majority The Republicans lost their narrow majority in Congress at the midterm elections.','retain a majority formal (= keep a majority ) They were able to retain an absolute majority of seats.','defend a majority (= try not to lose it ) He is defending a majority of 400 against his Labour opponent.','overturn a majority (= win a majority that previously belonged to someone else ) She hoped to overturn a Tory majority of 2,221.','a large majority Parliament voted by a large majority in favour of the ban.','a huge majority (= a very big majority ) Gone are the days of huge majorities and easy victories.','a small majority Their small majority made them worried about winning the next election.','a slim/narrow majority (= a very small majority ) The proposal was passed by a slim majority.','an overall majority (= more votes than anyone else ) What happens if no candidate receives an overall majority?','an overwhelming majority (= a large majority ) The resolution was passed by an overwhelming majority.','an absolute/outright/clear majority (= a majority that has been won by more than half the votes ) There was no party with an absolute majority in the House of Commons.','a simple majority (= a majority that has been won by most of the votes ) A simple majority of the people at the meeting were in favour of the changes.','a two-thirds/2:1/three to one etc majority A two-thirds majority in both Houses of Congress is needed to overturn a presidential veto.','a Labour/Democratic/Tory etc majority Republican majorities were elected in both Houses of Congress that year.','a parliamentary majority (= one that has enough seats in parliament to control it ) Labour increased its parliamentary majority.','a majority vote The majority vote carries the resolution.','the majority party (= the party with the most seats in a parliament ) At that time, Labour was the majority party in Parliament.','majority support (= votes or support given by the most number of people ) a solution that will command majority support in the House']::text[],'[{"sentence":"He won by a majority of 500.","translation":"او با اکثریت 500 رای پیروز شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001566938.mp3"},{"sentence":"The Labour Party won a huge majority at the last general election.","translation":"حزب کارگر در انتخابات سراسری گذشته اکثریت عظیمی را به دست آورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001566939.mp3"},{"sentence":"The party won an absolute majority in Portugal in 1987.","translation":"این حزب در سال 1987 اکثریت مطلق را در پرتغال به دست آورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001566945.mp3"},{"sentence":"The government gained only a narrow majority, with 151 votes against 144.","translation":"دولت با 151 رای در مقابل 144 رای تنها اکثریت محدود را به دست آورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752830.mp3"},{"sentence":"The Labour majority was reduced to just 15 seats at the last election.","translation":"اکثریت حزب کارگر در انتخابات گذشته به تنها 15 کرسی کاهش یافت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001566948.mp3"}]'::jsonb,5),
('3eb3a80e-3825-5571-a93c-497b606247aa','5d13c91a-7fb0-52c6-b291-ed03d607d888',3,null,null,'spoken & written',null,null,'majority vote/decision/verdict etc','اکثریت، بیشتر (گروه)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('3d39119d-3c5a-58e8-b974-51cfefdce780','5d13c91a-7fb0-52c6-b291-ed03d607d888',4,null,null,'spoken & written',null,null,'majority stake/shareholding etc','اکثریت، بیشتر (گروه)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('e00b8c01-20d4-55ea-8d25-87bf416b3fce','5d13c91a-7fb0-52c6-b291-ed03d607d888',5,'becoming an adult','بالغ شدن','law','the age when someone legally becomes an adult','[ uncountable ]',null,'سنی که شخصی به طور قانونی بالغ می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He became a partner in the family firm on reaching his majority.","translation":"او با رسیدن به اکثریت خود در شرکت خانوادگی شریک شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752844.mp3"}]'::jsonb,1),
('438ef829-5c0d-5d55-af7e-03ac4ecf2909','1b3abf84-c899-509b-aa30-2a650696e03d',1,null,null,'spoken & written','the relationship between two people who are married , or the state of being married','[ countable, uncountable ]',null,'ازدواج، پیوند زناشویی؛ مراسم عروسی','{}'::text[],'{}'::text[],array['a happy/unhappy marriage Ours was a very happy marriage.','a successful marriage The key to a successful marriage is friendship.','a failed/broken marriage After two failed marriages, she was not willing to risk marrying again.','somebody’s first/second etc marriage She had two children from her first marriage.','a previous marriage Anne is his daughter from a previous marriage.','an arranged marriage (= when your parents choose the person you will marry ) In their culture, there is a tradition of arranged marriage.','a same-sex/gay marriage (= a marriage between two homosexual people, which is not legal in many places ) a proposal to allow same-sex marriage in the state','a mixed marriage (= between people of different races or religions ) Her parents disapproved of mixed marriages.','an interracial marriage (= between people of different races ) Interracial marriage is more common than it used to be.','a loveless marriage Why should I stay in a loveless marriage?','a childless marriage It was a happy but childless marriage.','have a long/happy etc marriage They have a happy marriage.','a marriage ends Her three marriages all ended in divorce.','a marriage breaks down/up (= ends because of disagreements ) Liz’s marriage broke up after only eight months.','save your marriage (= do things to try to stay together as a married couple ) They’re going to counseling to try to save their marriage.','propose marriage formal (= ask someone to marry you ) He plucked up the courage to propose marriage to her.','consummate a marriage formal (= make your marriage complete by having sex ) She claimed that he abused her and never consummated the marriage.','a marriage is annulled formal (= is officially ended by a court or church ) Henry VIII had his first marriage annulled.','the breakdown/breakup of somebody’s marriage (= the end of it ) The breakup of her marriage had a devastating effect on her.','a proposal of marriage formal (= when someone asks you to marry them ) She rejected his proposal of marriage.','be born outside marriage (= be born when your parents are not married ) Four in ten children are born outside marriage.','sex before/outside marriage Her religious beliefs prevented sex before marriage.','ask for somebody’s hand in marriage old-fashioned (= ask someone to marry you, or ask their parents for permission to marry ) He asked my father for my hand in marriage.','the sanctity of marriage formal (= marriage seen as something that is very important and must be preserved and respected )']::text[],'[{"sentence":"She has three daughters from a previous marriage.","translation":"او از ازدواج قبلی سه دختر دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572002.mp3"},{"sentence":"his marriage to Marilyn Monroe","translation":"ازدواج او با مرلین مونرو","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001753999.mp3"},{"sentence":"In Denmark they have legalized marriage between gay couples.","translation":"در دانمارک ازدواج بین زوج های همجنس گرا را قانونی کرده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001754002.mp3"}]'::jsonb,3),
('fcf7e5a1-4a8e-5d80-b435-35fc8cde59d7','1b3abf84-c899-509b-aa30-2a650696e03d',2,null,null,'spoken & written','the ceremony in which two people get married','[ countable ]',null,'مراسمی که در آن دو نفر ازدواج می کنند',array['wedding']::text[],'{}'::text[],array['a happy/unhappy marriage Ours was a very happy marriage.','a successful marriage The key to a successful marriage is friendship.','a failed/broken marriage After two failed marriages, she was not willing to risk marrying again.','somebody’s first/second etc marriage She had two children from her first marriage.','a previous marriage Anne is his daughter from a previous marriage.','an arranged marriage (= when your parents choose the person you will marry ) In their culture, there is a tradition of arranged marriage.','a same-sex/gay marriage (= a marriage between two homosexual people, which is not legal in many places ) a proposal to allow same-sex marriage in the state','a mixed marriage (= between people of different races or religions ) Her parents disapproved of mixed marriages.','an interracial marriage (= between people of different races ) Interracial marriage is more common than it used to be.','a loveless marriage Why should I stay in a loveless marriage?','a childless marriage It was a happy but childless marriage.','have a long/happy etc marriage They have a happy marriage.','a marriage ends Her three marriages all ended in divorce.','a marriage breaks down/up (= ends because of disagreements ) Liz’s marriage broke up after only eight months.','save your marriage (= do things to try to stay together as a married couple ) They’re going to counseling to try to save their marriage.','propose marriage formal (= ask someone to marry you ) He plucked up the courage to propose marriage to her.','consummate a marriage formal (= make your marriage complete by having sex ) She claimed that he abused her and never consummated the marriage.','a marriage is annulled formal (= is officially ended by a court or church ) Henry VIII had his first marriage annulled.','the breakdown/breakup of somebody’s marriage (= the end of it ) The breakup of her marriage had a devastating effect on her.','a proposal of marriage formal (= when someone asks you to marry them ) She rejected his proposal of marriage.','be born outside marriage (= be born when your parents are not married ) Four in ten children are born outside marriage.','sex before/outside marriage Her religious beliefs prevented sex before marriage.','ask for somebody’s hand in marriage old-fashioned (= ask someone to marry you, or ask their parents for permission to marry ) He asked my father for my hand in marriage.','the sanctity of marriage formal (= marriage seen as something that is very important and must be preserved and respected )']::text[],'[{"sentence":"The marriage took place at St Bartholomew’s Church.","translation":"این ازدواج در کلیسای سنت بارتولومئوس انجام شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000186989.mp3"}]'::jsonb,1),
('d0a01e2a-bf7e-56cd-8a11-1e7500933cae','1b3abf84-c899-509b-aa30-2a650696e03d',3,null,null,'spoken & written',null,null,'by marriage','ازدواج، پیوند زناشویی؛ مراسم عروسی','{}'::text[],'{}'::text[],array['a happy/unhappy marriage Ours was a very happy marriage.','a successful marriage The key to a successful marriage is friendship.','a failed/broken marriage After two failed marriages, she was not willing to risk marrying again.','somebody’s first/second etc marriage She had two children from her first marriage.','a previous marriage Anne is his daughter from a previous marriage.','an arranged marriage (= when your parents choose the person you will marry ) In their culture, there is a tradition of arranged marriage.','a same-sex/gay marriage (= a marriage between two homosexual people, which is not legal in many places ) a proposal to allow same-sex marriage in the state','a mixed marriage (= between people of different races or religions ) Her parents disapproved of mixed marriages.','an interracial marriage (= between people of different races ) Interracial marriage is more common than it used to be.','a loveless marriage Why should I stay in a loveless marriage?','a childless marriage It was a happy but childless marriage.','have a long/happy etc marriage They have a happy marriage.','a marriage ends Her three marriages all ended in divorce.','a marriage breaks down/up (= ends because of disagreements ) Liz’s marriage broke up after only eight months.','save your marriage (= do things to try to stay together as a married couple ) They’re going to counseling to try to save their marriage.','propose marriage formal (= ask someone to marry you ) He plucked up the courage to propose marriage to her.','consummate a marriage formal (= make your marriage complete by having sex ) She claimed that he abused her and never consummated the marriage.','a marriage is annulled formal (= is officially ended by a court or church ) Henry VIII had his first marriage annulled.','the breakdown/breakup of somebody’s marriage (= the end of it ) The breakup of her marriage had a devastating effect on her.','a proposal of marriage formal (= when someone asks you to marry them ) She rejected his proposal of marriage.','be born outside marriage (= be born when your parents are not married ) Four in ten children are born outside marriage.','sex before/outside marriage Her religious beliefs prevented sex before marriage.','ask for somebody’s hand in marriage old-fashioned (= ask someone to marry you, or ask their parents for permission to marry ) He asked my father for my hand in marriage.','the sanctity of marriage formal (= marriage seen as something that is very important and must be preserved and respected )']::text[],'[]'::jsonb,0),
