('0742e121-de36-578b-9e96-29e1ebc5df35','466d4de8-16c5-5f08-a9e5-0152e61a0f34',1,null,null,'spoken & written','relating to your money, possessions , living conditions etc, rather than the needs of your mind or soul',null,null,'مادی، معیشتی (نیازها)؛ مهم (به‌حساب آمده)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The spiritual life is more important than material possessions.","translation":"زندگی معنوی مهمتر از دارایی های مادی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000191005.mp3"},{"sentence":"a society that places high importance on material rewards","translation":"جامعه ای که به پاداش های مادی اهمیت زیادی می دهد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001757476.mp3"}]'::jsonb,2),
('e5211131-17f9-5fbc-a6b5-b8bb5fbf6556','466d4de8-16c5-5f08-a9e5-0152e61a0f34',2,null,null,'spoken & written','relating to the real world and physical objects, rather than religious or spiritual things',null,null,'مربوط به دنیای واقعی و اشیاء فیزیکی است، نه چیزهای مذهبی یا معنوی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"According to some, the material world is all that exists.","translation":"به عقیده برخی، جهان مادی همه آن چیزی است که وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572576.mp3"}]'::jsonb,1),
