('97669ff1-c452-50d0-9ca7-a03cbb1300c0','d971e0ab-0743-5cb4-afb8-03ddc8d4cef4',1,null,null,'spoken & written','connected with the Middle Ages (= the period between about 1100 and 1500 AD )',null,null,'قرون‌وسطایی، مربوط به قرون وسطی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"These spices were first brought to Italy from the East in medieval times.","translation":"این ادویه ها اولین بار در قرون وسطی از شرق به ایتالیا آورده شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714951.mp3"},{"sentence":"a medieval castle","translation":"یک قلعه قرون وسطایی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714952.mp3"}]'::jsonb,2),
