('8bc9702a-f286-54a5-b42f-b1687db42fdd','c78073f5-8ec0-5947-8c5b-a127dd981f0b',2,null,null,'formal','a statement or expression that means ‘no’',null,null,'عبارت یا عبارتی به معنای "نه"','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The majority of people, when asked whether or not they are creative, will reply in the negative .","translation":"اکثر مردم وقتی از آنها سوال می شود که آیا خلاق هستند یا نه، پاسخ منفی خواهند داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762590.mp3"}]'::jsonb,1),
