('0ca20ec5-c7b7-5d40-9016-7191bbad7835','ca2267ef-71ad-562d-b0b0-6be646fd8cde',1,null,null,'spoken & written','in or from the north of a country or area',null,null,'شمالی، شمالی‌تر (کشور)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a man with a northern accent","translation":"مردی با لهجه شمالی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000246555.mp3"},{"sentence":"Northern Europe","translation":"اروپای شمالی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000246556.mp3"}]'::jsonb,2),
('ec21fea6-f594-5149-97e4-5d9b2ffb0931','8394f783-1ce4-503d-ac0e-997c81f6216c',1,null,null,'spoken & written','now, compared with what happened in the past',null,null,'در روزگار ما، این روزها؛ امروز (مقایسه)',array['today']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Nowadays people are rarely shocked by the sex they see on television.","translation":"امروزه مردم به ندرت از رابطه جنسی که در تلویزیون می بینند شوکه می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000249048.mp3"},{"sentence":"Most people nowadays are aware of the importance of a healthy diet.","translation":"امروزه بیشتر مردم از اهمیت یک رژیم غذایی سالم آگاه هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573313.mp3"}]'::jsonb,2),
('64f9f107-267c-52b8-8dc3-0c067ddfda96','96af8194-208c-5138-bf44-b11b74ad6ec6',1,null,null,'spoken & written','a person, thing, or situation that annoys you or causes problems','[ countable usually singular ]',null,'درسر، مزاحم؛ دردسر (چیز)؛ مزاحمت (بازی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The dogs next door are a real nuisance.","translation":"سگ های همسایه واقعاً مزاحم هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573445.mp3"},{"sentence":"What a nuisance! I’ve forgotten my ticket.","translation":"چه مزاحمتی! بلیطم را فراموش کرده ام","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000249683.mp3"},{"sentence":"I hate to be a nuisance, but could you move your car to the other side of the street?","translation":"من از مزاحم بودن متنفرم، اما آیا می توانید ماشین خود را به آن طرف خیابان ببرید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573449.mp3"},{"sentence":"Stop making a nuisance of yourself (= annoying other people with your behaviour ) !","translation":"از ایجاد مزاحمت برای خود (= آزار دیگران با رفتار خود) دست بردارید!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573450.mp3"},{"sentence":"It’s a nuisance having to get up that early on a Sunday morning.","translation":"این یک مزاحم است که صبح یکشنبه آنقدر زود بیدار شوید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573455.mp3"}]'::jsonb,5),
('7b013dcf-a931-58f1-90f0-90e6552657ba','96af8194-208c-5138-bf44-b11b74ad6ec6',2,null,null,'law','the use of a place or property in a way that causes public annoyance','[ countable, uncountable ]',null,'استفاده از مکان یا ملک به نحوی که موجب آزار عمومی شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The nightclub has been declared a public nuisance .","translation":"کلوپ شبانه مزاحم عمومی اعلام شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573458.mp3"}]'::jsonb,1),
('2343cedd-4148-565b-a541-de421b755a4f','d9f3b519-7d7f-5d59-8ed0-52079a665d43',1,null,null,'spoken & written','many',null,null,'بسیار، فراوان (تعداد)؛ متعدد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Numerous attempts have been made to hide the truth.","translation":"تلاش های زیادی برای پنهان کردن حقیقت صورت گرفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000250079.mp3"},{"sentence":"The two leaders have worked together on numerous occasions .","translation":"این دو رهبر در موارد متعدد با هم کار کرده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000250080.mp3"},{"sentence":"The individuals who have contributed to this book are far too numerous to mention.","translation":"افرادی که در این کتاب مشارکت داشته اند بسیار زیاد هستند که نمی توان آنها را نام برد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574605.mp3"},{"sentence":"There were a lot of mistakes in his essay.","translation":"در مقاله او اشتباهات زیادی وجود داشت.","audio_url":null}]'::jsonb,4),
('fcea2e76-744d-5261-a1ab-6c158d054475','58514bdb-44a6-5a6f-a100-0f26e05f00e2',1,'time','زمان','spoken & written','a time when something happens','[ countable ]',null,'مناسبت، موقعیت؛ وقت (نوبت)؛ مناسبت (خاص)','{}'::text[],'{}'::text[],array['several occasions He has helped me on several occasions.','many occasions I have seen him drunk on many occasions.','numerous occasions She has been late on numerous occasions.','two/three etc occasions He was given a red card on two occasions this season.','a rare occasion (= used when something does not happen often ) Only on rare occasions did she ever receive a letter.','a particular occasion On that particular occasion, he greeted me by kissing my hand.','a previous occasion He insisted then, as on every previous occasion, that he was innocent.','a separate occasion I had heard this story on at least four separate occasions.','a different occasion The same person can react differently on different occasions.','such occasions (= an occasion like the one mentioned or described ) He had a box of toys by his desk for such occasions.','a number of occasions The crowd interrupted her speech on a number of occasions.','more than one occasion (= more than once ) She stayed out all night on more than one occasion.','at least one occasion (= once, and probably more than once ) On at least one occasion he was arrested for robbery.']::text[],'[{"sentence":"I’ve seen Jana with them on several occasions.","translation":"من جانا را چندین بار با آنها دیدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000258058.mp3"},{"sentence":"On this occasion we were sitting in a park in Madrid.","translation":"به همین مناسبت در پارکی در مادرید نشسته بودیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536188.mp3"},{"sentence":"She had met Zahid on two separate occasions.","translation":"او در دو نوبت جداگانه با زاهد ملاقات کرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000258057.mp3"},{"sentence":"This was the occasion for expressions of friendship by the two presidents.","translation":"این فرصتی بود برای ابراز دوستی دو رئیس جمهور.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536189.mp3"}]'::jsonb,4),
('02a64b5c-e4c8-597c-acd7-dcdad24069b5','58514bdb-44a6-5a6f-a100-0f26e05f00e2',2,'special event','رویداد ویژه','spoken & written','an important social event or ceremony','[ countable ]',null,'یک رویداد یا مراسم مهم اجتماعی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m saving this bottle of champagne for a special occasion.","translation":"من این بطری شامپاین را برای یک موقعیت خاص ذخیره می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536190.mp3"}]'::jsonb,1),
('5b63ef82-4166-5de6-a160-9ff9b446a596','58514bdb-44a6-5a6f-a100-0f26e05f00e2',3,'cause/reason','علت/دلیل','formal','a cause or reason','[ uncountable ]',null,'یک علت یا دلیل','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"His remark was the occasion of a bitter quarrel.","translation":"سخنان او به مناسبت یک دعوای تلخ بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536200.mp3"},{"sentence":"I had occasion to call on him last year.","translation":"سال گذشته فرصتی داشتم که با او تماس بگیرم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001760129.mp3"}]'::jsonb,2),
('c565422b-ad37-57c9-abed-ed2c5fb2ca3b','58514bdb-44a6-5a6f-a100-0f26e05f00e2',4,null,null,'spoken & written',null,null,'if (the) occasion arises','مناسبت، موقعیت؛ وقت (نوبت)؛ مناسبت (خاص)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ba605d6c-4585-5ba4-8ec9-6b1dad1a7d9f','58514bdb-44a6-5a6f-a100-0f26e05f00e2',5,null,null,'spoken & written',null,null,'on occasion','مناسبت، موقعیت؛ وقت (نوبت)؛ مناسبت (خاص)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('4c16e6ca-f77c-58a3-90c1-4303be62e338','58514bdb-44a6-5a6f-a100-0f26e05f00e2',6,null,null,'spoken & written',null,null,'on the occasion of something','مناسبت، موقعیت؛ وقت (نوبت)؛ مناسبت (خاص)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('3791a139-080f-508e-aabb-22a0f9cc1cf4','7ef3452e-59ad-587e-849a-02e3fbfa0e70',1,null,null,'spoken & written','to cause something',null,null,'باعث چیزی شدن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She had a long career break occasioned by her husband’s job being moved to Paris.","translation":"او یک وقفه شغلی طولانی داشت که ناشی از انتقال شغل همسرش به پاریس بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000258128.mp3"},{"sentence":"Your behaviour has occasioned us a great deal of anxiety.","translation":"رفتار شما باعث نگرانی ما شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000258131.mp3"}]'::jsonb,2),
('32f003fc-60dc-599d-80e5-c068b09dd727','676455fa-3b27-58dc-8fb9-401ee1882bb2',1,null,null,'spoken & written','someone who is in a position of authority in an organization',null,null,'مسؤول، کارمند (دولت)؛ مقام رسمی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a government official","translation":"یک مقام دولتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000260722.mp3"},{"sentence":"senior administration officials","translation":"مقامات ارشد دولت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000260721.mp3"}]'::jsonb,2),
('2ad43d4d-861e-5f95-914d-76cb3f9f6397','3d1e9ebf-8925-5a92-a323-3557bede0964',1,null,null,'spoken & written','approved of or done by someone in authority, especially the government',null,null,'رسمی، اداری؛ رسمی (اعلام)؛ مجاز (تأیید)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an official investigation into the causes of the explosion","translation":"تحقیقات رسمی در مورد علل انفجار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762230.mp3"},{"sentence":"the official policy on education","translation":"سیاست رسمی آموزش و پرورش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762231.mp3"},{"sentence":"official statistics about illegal drug use","translation":"آمار رسمی مصرف مواد مخدر غیرقانونی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001565976.mp3"},{"sentence":"You will have to get official permission first.","translation":"ابتدا باید مجوز رسمی دریافت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001565970.mp3"},{"sentence":"Finally the letter of appointment came, making it all official.","translation":"بالاخره نامه انتصاب آمد و همه چیز را رسمی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762232.mp3"}]'::jsonb,5),
('33cd1711-af28-53bd-aab3-db2bfe7ad63b','3d1e9ebf-8925-5a92-a323-3557bede0964',2,null,null,'spoken & written','relating to or done as part of an important job or position',null,null,'مربوط به یا به عنوان بخشی از یک شغل یا موقعیت مهم انجام می شود','{}'::text[],'{}'::text[],array['an official visit/engagement etc (= one that relates to an important job or position ) The prime minister was on an official visit to China.','somebody''s official duties (= the things someone does as part of their job or position ) the royal family''s official duties.','an official residence (= a house someone is able to use as part of their important job ) the ambassador''s official residence in London','somebody''s official capacity (= someone''s official position or duty ) He spent Wednesday in Washington acting in his official capacity as Senate majority leader.']::text[],'[{"sentence":"The president was leaving for a four-day official tour of Mexico.","translation":"رئیس جمهور برای یک تور رسمی چهار روزه مکزیک را ترک کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762235.mp3"},{"sentence":"the Queen’s performance of official duties","translation":"انجام وظایف رسمی ملکه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762236.mp3"},{"sentence":"They dined in an official capacity with other European leaders.","translation":"آنها در مقام رسمی با دیگر رهبران اروپایی شام خوردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762239.mp3"},{"sentence":"the Lord Mayor’s official residence","translation":"اقامتگاه رسمی شهردار لرد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762243.mp3"}]'::jsonb,4),
('9d05bc91-54be-5e58-97ba-f17572a2bed9','3d1e9ebf-8925-5a92-a323-3557bede0964',3,null,null,'spoken & written','an official explanation , account etc is one that is given formally and publicly, but may not be true',null,null,'توضیح رسمی، حساب و غیره توضیحی است که به صورت رسمی و عمومی ارائه می شود، اما ممکن است درست نباشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Many doubted the official version of events.","translation":"بسیاری به نسخه رسمی رویدادها شک داشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001565995.mp3"},{"sentence":"The official line (= what is said publicly by people in authority ) was that the troops were there to protect the King.","translation":"خط رسمی (= آنچه به طور علنی توسط افراد صاحب قدرت گفته می شود) این بود که سربازان آنجا بودند تا از پادشاه محافظت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762249.mp3"}]'::jsonb,2),
('bccd05ba-c62b-5020-a8ff-362a49418356','3d1e9ebf-8925-5a92-a323-3557bede0964',4,null,null,'spoken & written','chosen to represent someone or an organization, or do something for them',null,null,'انتخاب شده تا نماینده کسی یا سازمانی باشد یا کاری برای آنها انجام دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the company’s official logo","translation":"لوگوی رسمی شرکت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000260752.mp3"},{"sentence":"the official representative from the American administration","translation":"نماینده رسمی دولت آمریکا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762250.mp3"}]'::jsonb,2),
('88796b4a-b68a-544a-b219-672f5594b699','3d1e9ebf-8925-5a92-a323-3557bede0964',5,null,null,'spoken & written','an official event is a formal public event',null,null,'یک رویداد رسمی یک رویداد عمومی رسمی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The official opening of the institute was in May.","translation":"افتتاحیه رسمی موسسه در اردیبهشت ماه بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000260756.mp3"}]'::jsonb,1),
('dc8630e0-bd1f-5cf3-85cf-bc4e2d1bf86b','20fe1d51-3d26-53d1-831b-40ac87cbd16c',1,null,null,'spoken & written','someone who works on a telephone switchboard , who you can call for help',null,null,'بهره‌بردار، اپراتور؛ مسئول تعویض (سوئیچ)؛ عامل (بازی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Hello, operator? Could you put me through to Room 31?","translation":"سلام اپراتور؟ آیا می توانید مرا به اتاق 31 بفرستید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536441.mp3"}]'::jsonb,1),
('1d2ad06a-21e3-541d-85d5-4e69d515cfb2','20fe1d51-3d26-53d1-831b-40ac87cbd16c',2,null,null,'spoken & written','someone who operates a machine or piece of equipment',null,null,'کسی که ماشین یا قطعه ای را اداره می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"computers which can be used by untrained operators","translation":"کامپیوترهایی که می توانند توسط اپراتورهای آموزش ندیده استفاده شوند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266864.mp3"}]'::jsonb,1),
('2c957e5d-4846-557d-aea2-16871c8f7a75','20fe1d51-3d26-53d1-831b-40ac87cbd16c',3,null,null,'spoken & written','a person or company that operates a particular business',null,null,'شخص یا شرکتی که یک تجارت خاص را اداره می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"new regulations affecting taxi operators","translation":"مقررات جدید بر تاکسیرانی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266869.mp3"},{"sentence":"Julian travelled with Caribbean Connection, the UK''s leading Caribbean tour operator (= company that arranges holidays ) .","translation":"جولیان با Caribbean Connection، اپراتور پیشرو تورهای کارائیب در بریتانیا (= شرکتی که تعطیلات را ترتیب می دهد) سفر کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764655.mp3"},{"sentence":"a private operator running regular passenger services","translation":"یک اپراتور خصوصی که خدمات مسافری منظم را اجرا می کند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001824497.mp3"}]'::jsonb,3),
('83e8ca31-9c8d-512c-af31-3b3b88a215eb','20fe1d51-3d26-53d1-831b-40ac87cbd16c',4,null,null,'spoken & written','someone who is good at achieving things by persuading people to help or agree with them',null,null,'کسی که با متقاعد کردن افراد به کمک یا موافقت با آنها در دستیابی به چیزهایی خوب است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Monsieur Valentin was a formidable political operator.","translation":"مسیو والنتین یک اپراتور سیاسی قدرتمند بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266873.mp3"},{"sentence":"He may not look it, but Newman is a smooth operator (= someone who is good at persuading people but who you feel you cannot trust ) .","translation":"او ممکن است به نظر نرسد، اما نیومن یک اپراتور ساده است (= کسی که در متقاعد کردن مردم خوب است اما فکر می کنید نمی توانید به او اعتماد کنید).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266876.mp3"}]'::jsonb,2),
('b1658430-aa5b-51bf-9ff1-4ce2e8b3b06b','f9b009f8-a4ab-534d-926c-8266413c8978',1,null,null,'spoken & written','someone who you try to defeat in a competition , game, fight, or argument',null,null,'حریف، رقیب؛ مخالف (پیشنهاد)','{}'::text[],'{}'::text[],array['somebody''s main/chief opponent Who was her main opponent for the presidential nomination?','a leading opponent (= one of the main opponents ) In July the authorities arrested two leading opponents of the government.','a strong/tough opponent (= one that is difficult to defeat ) Arizona is a strong opponent, but the Oregon team intend to beat them.','a formidable opponent (= a very strong opponent ) In debate, he was a formidable opponent.','a dangerous opponent (= one who might defeat you ) In tomorrow''s match, he will take on his most dangerous opponent.','a political opponent the president''s political opponents','a worthy opponent (= one who deserves respect ) The Democratic Senator has shown himself to be a worthy opponent.','face an opponent The team were facing their final opponent of the season.','defeat an opponent She came within three points of defeating her opponent.','outfox/outwit/outmanoeuvre an opponent (= gain an advantage over an opponent by being more intelligent or skilful than they are ) Football is all about outwitting your opponents.']::text[],'[{"sentence":"Graf’s opponent in today’s final will be Sukova.","translation":"حریف گراف در فینال امروز سوکووا خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267129.mp3"},{"sentence":"During the primary elections, McCain was Bush’s leading opponent.","translation":"در طول انتخابات مقدماتی، مک کین رقیب اصلی بوش بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764675.mp3"},{"sentence":"In debate he was a formidable opponent.","translation":"در مناظره او یک حریف سرسخت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764678.mp3"},{"sentence":"He is admired even by his political opponents .","translation":"او حتی توسط مخالفان سیاسی خود تحسین می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536487.mp3"}]'::jsonb,4),
('76d5605c-6545-52e4-805c-0b4263e07d10','f9b009f8-a4ab-534d-926c-8266413c8978',2,null,null,'spoken & written','someone who disagrees with a plan, idea, or system and wants to try to stop or change it',null,null,'کسی که با یک طرح، ایده یا سیستم مخالف است و می‌خواهد آن را متوقف یا تغییر دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Rodgers was not an opponent of the new airport.","translation":"راجرز مخالف فرودگاه جدید نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267136.mp3"},{"sentence":"an outspoken opponent of gun control","translation":"یک مخالف صریح کنترل اسلحه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764679.mp3"}]'::jsonb,2),
('6453c3a7-b9a7-5112-aa8a-4a9914e7a51e','14487877-d609-5292-bfcd-46445efe140c',1,null,null,'spoken & written','if one thing or person is opposite another, they are facing each other',null,null,'روبرویِ، مقابلِ (مکان)؛ مخالف (نظر)؛ مقابل (بازی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The people sitting opposite us looked very familiar.","translation":"افرادی که روبروی ما نشسته بودند بسیار آشنا به نظر می رسیدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267319.mp3"},{"sentence":"on the wall opposite the door","translation":"روی دیوار روبروی در","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001578271.mp3"}]'::jsonb,2),
('ebfc128c-0669-53af-9737-03095c482b82','14487877-d609-5292-bfcd-46445efe140c',2,null,null,'spoken & written',null,null,'play/star/appear etc opposite somebody','روبرویِ، مقابلِ (مکان)؛ مخالف (نظر)؛ مقابل (بازی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('570dec4a-6953-5857-a0c8-4c46ed639dba','b73c1ccd-8321-5439-8d07-1247d430f341',1,null,null,'spoken & written','as different as possible from something else',null,null,'تا حد امکان متفاوت از چیزهای دیگر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I thought the medicine would make him sleep, but it had the opposite effect .","translation":"فکر می کردم این دارو باعث خوابیدن او می شود، اما نتیجه معکوس داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267329.mp3"},{"sentence":"two parties at opposite ends of the political spectrum","translation":"دو حزب در دو طرف طیف سیاسی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267330.mp3"},{"sentence":"At the opposite extreme, Ashworth’s style is very simple and modern.","translation":"در نقطه مقابل، سبک اشورث بسیار ساده و مدرن است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001578282.mp3"},{"sentence":"Bob was quicker than Ed? It’s usually the opposite way round .","translation":"باب سریعتر از اد بود؟ معمولاً برعکس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001578285.mp3"},{"sentence":"a political philosophy that was opposite to everything she believed in","translation":"یک فلسفه سیاسی که مخالف هر چیزی بود که او به آن اعتقاد داشت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001763813.mp3"}]'::jsonb,5),
('5b56748a-0ee1-5aa6-b318-e098eef50565','b73c1ccd-8321-5439-8d07-1247d430f341',2,null,null,'spoken & written','the opposite direction , way etc is directly away from someone or something',null,null,'جهت مخالف، راه و غیره مستقیماً از کسی یا چیزی دور است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She turned and walked off in the opposite direction .","translation":"چرخید و در جهت مخالف رفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267334.mp3"},{"sentence":"But the sign was pointing the opposite way .","translation":"اما تابلو برعکس را نشان می داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001578290.mp3"}]'::jsonb,2),
('28964e9d-e4a5-52fc-8770-cfacacd40e67','b73c1ccd-8321-5439-8d07-1247d430f341',3,null,null,'spoken & written','the opposite side, corner , edge etc of something is on the other side of the same area, often facing it',null,null,'طرف مقابل، گوشه، لبه و غیره چیزی در طرف دیگر همان ناحیه قرار دارد و اغلب رو به آن است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The store was on the opposite side of the street.","translation":"مغازه در طرف مقابل خیابان بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267338.mp3"},{"sentence":"the drawing on the opposite page","translation":"نقاشی در صفحه مقابل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001578296.mp3"},{"sentence":"They work at opposite ends of the country (= a long distance apart ) , so only see each other at weekends.","translation":"آنها در دو طرف کشور کار می کنند (= فاصله زیاد از هم)، بنابراین فقط آخر هفته ها یکدیگر را می بینند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267350.mp3"}]'::jsonb,3),
('74bf82e2-b0ed-578a-ae39-f34fd27709be','b73c1ccd-8321-5439-8d07-1247d430f341',4,null,null,'spoken & written',null,null,'the opposite sex',null,'{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('9809078f-c343-52d0-a23e-f069093cdf22','b73c1ccd-8321-5439-8d07-1247d430f341',5,null,null,'spoken & written',null,null,'somebody’s opposite number',null,'{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('33e9415e-1ed5-5f75-8b1a-03fdd6f71116','1a10f6a3-b81a-5022-a748-e238de7e3c6c',1,null,null,'spoken & written','a person or thing that is as different as possible from someone or something else',null,null,'شخص یا چیزی که تا حد امکان با شخص یا چیز دیگری متفاوت است','{}'::text[],'{}'::text[],array['the complete/total opposite She is the complete opposite of her sister.','the exact/precise/direct opposite My own experience says that the exact opposite is true.','the polar opposite of something ( also polar opposites ) (= used about two things, people etc that are completely opposite ) These two viewpoints seem like polar opposites. Mum was the polar opposite of dear old Dad.','the opposite is the case/is true People believe the Sun moved around the Earth, but Copernicus showed that the opposite was the case.','exactly/precisely the opposite (= completely different than what has been said ) It looks simple, but it is exactly the opposite.','the very opposite (= exactly the opposite ) Exercise does not increase the appetite - in fact, the very opposite is true.','just/quite the opposite (= exactly the opposite ) He wasn’t laughing. Quite the opposite, in fact.','do the opposite Whatever I tell him to do, he does the opposite.']::text[],'[{"sentence":"What’s the opposite of ‘optimistic’?","translation":"متضاد \"خوش بینانه\" چیست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267370.mp3"},{"sentence":"She’s quite shy, the exact opposite of Becky.","translation":"او کاملاً خجالتی است، دقیقاً برعکس بکی.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267373.mp3"},{"sentence":"The two men were complete opposites – Simon tall and fair, Clive short and dark.","translation":"این دو مرد کاملاً متضاد بودند - سیمون قد بلند و زیبا، کلایو کوتاه قد و تیره.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001578309.mp3"},{"sentence":"If anything, the opposite was true.","translation":"اگر چیزی بود، برعکس بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001578310.mp3"},{"sentence":"Is it sensible to think of masculine/feminine as polar opposites (= exactly or completely opposite ) ?","translation":"آیا معقول است که مذکر/مونث را متضادهای قطبی (= دقیقاً یا کاملاً متضاد) تصور کنیم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001824510.mp3"}]'::jsonb,5),
('d6fe83ff-62cc-5b54-ba08-344231a78529','1a10f6a3-b81a-5022-a748-e238de7e3c6c',2,null,null,'spoken & written',null,null,'not ... just/quite the opposite',null,'{}'::text[],'{}'::text[],array['the complete/total opposite She is the complete opposite of her sister.','the exact/precise/direct opposite My own experience says that the exact opposite is true.','the polar opposite of something ( also polar opposites ) (= used about two things, people etc that are completely opposite ) These two viewpoints seem like polar opposites. Mum was the polar opposite of dear old Dad.','the opposite is the case/is true People believe the Sun moved around the Earth, but Copernicus showed that the opposite was the case.','exactly/precisely the opposite (= completely different than what has been said ) It looks simple, but it is exactly the opposite.','the very opposite (= exactly the opposite ) Exercise does not increase the appetite - in fact, the very opposite is true.','just/quite the opposite (= exactly the opposite ) He wasn’t laughing. Quite the opposite, in fact.','do the opposite Whatever I tell him to do, he does the opposite.']::text[],'[]'::jsonb,0),
('6816ef92-bf93-53c3-aa0d-598edb2acdb9','1a10f6a3-b81a-5022-a748-e238de7e3c6c',3,null,null,'spoken & written',null,null,'opposites attract',null,'{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('6ef63e02-a82e-51ad-b928-a66f9f6fedce','a8b75ef1-70b5-5e2b-9d2b-aadfae98a9b3',1,null,null,'spoken & written','in a position on the other side of the same area',null,null,'در موقعیتی در طرف دیگر همان منطقه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Hannah lives just opposite.","translation":"هانا درست در مقابل زندگی می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267387.mp3"}]'::jsonb,1),
('0cb7bac1-3ad4-5ffe-8f5f-85e264e22742','75d3f572-4be9-5f0f-8e96-98e212b32aea',1,null,null,'spoken & written','average , common , or usual , not different or special',null,null,'معمولی، عادی؛ معمولی (مردم)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s just an ordinary camera.","translation":"این فقط یک دوربین معمولی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713830.mp3"},{"sentence":"The book is about ordinary people .","translation":"کتاب درباره مردم عادی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000269114.mp3"},{"sentence":"Art should be part of ordinary life .","translation":"هنر باید بخشی از زندگی عادی باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001824531.mp3"},{"sentence":"It is good because it is written in friendly, ordinary language.","translation":"خوب است زیرا به زبانی دوستانه و معمولی نوشته شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001824535.mp3"},{"sentence":"Anything out of the ordinary made her nervous.","translation":"هر چیز غیر عادی او را عصبی می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713834.mp3"},{"sentence":"The money is taxed as income in the ordinary way.","translation":"پول به عنوان درآمد به روش معمول مالیات می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000269124.mp3"},{"sentence":"This is no ordinary car.","translation":"این ماشین معمولی نیست","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713842.mp3"},{"sentence":"Ruiz is no ordinary prisoner.","translation":"رویز یک زندانی معمولی نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713843.mp3"}]'::jsonb,8),
('70a8b569-11ac-5a73-b2af-042f9c68b427','75d3f572-4be9-5f0f-8e96-98e212b32aea',2,null,null,'spoken & written','not particularly good or impressive',null,null,'به خصوص خوب یا چشمگیر نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I thought the paintings were pretty ordinary.","translation":"به نظر من نقاشی ها خیلی معمولی بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000269128.mp3"}]'::jsonb,1),
('543a6229-7e3a-571f-a51e-f27e220d18f8','5f751ed4-3c5b-54bf-8135-f2b7737d1d44',1,null,null,'spoken & written','to make the necessary arrangements so that an activity can happen effectively','[ transitive ]',null,'سازمان‌دهی کردن؛ ترتیب دادن؛ منظم کردن (اتاق)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The course was organized by a training company.","translation":"این دوره توسط یک شرکت آموزشی برگزار شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000379664.mp3"},{"sentence":"Students need to learn how to organize their work.","translation":"دانش آموزان باید یاد بگیرند که چگونه کار خود را سازماندهی کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713906.mp3"}]'::jsonb,2),
('a0dd6356-dc8f-5b9b-9b84-a5219caa6a16','5f751ed4-3c5b-54bf-8135-f2b7737d1d44',2,null,null,'spoken & written','to manage a group of people who are doing something','[ transitive ]',null,'برای مدیریت گروهی از افرادی که در حال انجام کاری هستند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The lawyer helped to organize a group of parents who took action for their children.","translation":"وکیل به سازماندهی گروهی از والدین کمک کرد که برای فرزندان خود اقدام کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000379670.mp3"},{"sentence":"The scientists need to organize themselves and work as a team.","translation":"دانشمندان باید خود را سازماندهی کنند و به صورت تیمی کار کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000379674.mp3"}]'::jsonb,2),
('8452ec97-3ef6-5ad4-bc01-455553890d48','5f751ed4-3c5b-54bf-8135-f2b7737d1d44',3,null,null,'spoken & written','to arrange something so that it is more ordered or happens in a more sensible way','[ transitive ]',null,'چیزی را به گونه ای ترتیب دادن که نظم بیشتری پیدا کند یا به نحو معقول تری اتفاق بیفتد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He doesn’t need you to organize his life for him.","translation":"او نیازی ندارد که شما زندگی اش را برای او سازماندهی کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713910.mp3"},{"sentence":"Organize yourself to arrive at places on time.","translation":"خود را سازماندهی کنید تا به موقع به مکان ها برسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001824546.mp3"}]'::jsonb,2),
('d5d661c7-8e14-550d-b2b5-ea2a4e7e7b9d','5f751ed4-3c5b-54bf-8135-f2b7737d1d44',4,null,null,'spoken & written','to arrange things in a particular order or pattern','[ transitive ]',null,'برای مرتب کردن چیزها در یک نظم یا الگوی خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We are learning about how genes are organized.","translation":"ما در مورد چگونگی سازماندهی ژن ها یاد می گیریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713914.mp3"}]'::jsonb,1),
('ec912b0f-89c6-5406-bf11-477f2abe493d','5f751ed4-3c5b-54bf-8135-f2b7737d1d44',5,null,null,'spoken & written','to form a trade union or persuade people to join one','[ intransitive, transitive ]',null,'برای تشکیل یک اتحادیه کارگری یا ترغیب مردم به عضویت در آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The law gives workers the right to organize and bargain collectively.","translation":"قانون به کارگران حق سازماندهی و چانه زنی جمعی را می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713915.mp3"}]'::jsonb,1),
('96d41084-ab40-50d8-9da6-9f466be72103','bed62b37-8965-5eb6-819a-67d6f7feaf41',1,null,null,'spoken & written','existing or happening first, before other people or things','[ only before noun ]',null,'اصلی، نخستین؛ اورجینال (نسخه)؛ خلاق (ایده)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The land was returned to its original owner.","translation":"زمین به صاحب اصلی خود بازگردانده شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000380072.mp3"},{"sentence":"The kitchen still has many original features (= parts that were there when the house was first built ) .","translation":"آشپزخانه هنوز دارای بسیاری از ویژگی های اصلی است (= قطعاتی که در زمان ساخت خانه در آنجا بودند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000380073.mp3"},{"sentence":"the original meaning of the word","translation":"معنی اصلی کلمه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567129.mp3"},{"sentence":"The original plan was to fly out to New York.","translation":"برنامه اولیه پرواز به نیویورک بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567130.mp3"}]'::jsonb,4),
('c85ab333-7586-5c5d-8fcc-bcdbef17d0e2','bed62b37-8965-5eb6-819a-67d6f7feaf41',2,null,null,'spoken & written','completely new and different from anything that anyone has thought of before',null,null,'کاملاً جدید و متفاوت از هر چیزی که قبلاً کسی به آن فکر کرده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I don’t think George is capable of having original ideas !","translation":"فکر نمی‌کنم جورج بتواند ایده‌های اصلی داشته باشد!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000380077.mp3"},{"sentence":"That’s not a very original suggestion.","translation":"این یک پیشنهاد خیلی اصلی نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567132.mp3"},{"sentence":"a highly original design","translation":"یک طراحی بسیار اصلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000380078.mp3"},{"sentence":"His work is truly original.","translation":"کار او واقعاً بدیع است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000562021.mp3"}]'::jsonb,4),
('e329a653-2de6-5bbf-9969-6f6e96a70d5b','bed62b37-8965-5eb6-819a-67d6f7feaf41',3,null,null,'spoken & written','an original work of art is the one that was made by the artist and is not a copy','[ only before noun ]',null,'اثر هنری اصلی، اثری است که توسط هنرمند ساخته شده باشد و کپی نباشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The original painting is now in the National Gallery in London.","translation":"نقاشی اصلی اکنون در گالری ملی لندن است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567140.mp3"},{"sentence":"an original Holbein drawing","translation":"یک نقاشی اصلی هلبین","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000380084.mp3"}]'::jsonb,2),
('5a456858-f8c4-575f-b65e-0496ba04fb6c','cdceafde-5346-5600-839c-2f0bf4ff6ce8',1,null,null,'spoken & written','a work of art or a document that is not a copy, but is the one produced by the writer or artist',null,null,'اثر هنری یا سندی که کپی نیست، بلکه توسط نویسنده یا هنرمند تولید شده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The colours are much more striking in the original.","translation":"رنگ ها در اصل بسیار چشمگیرتر هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000380094.mp3"},{"sentence":"I’ll keep a copy of the contract, and give you the original.","translation":"من یک کپی از قرارداد را نگه می دارم و اصل آن را به شما می دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000380095.mp3"}]'::jsonb,2),
('bcc5bafc-7a66-5186-be3a-4753be024e01','cdceafde-5346-5600-839c-2f0bf4ff6ce8',2,null,null,'spoken & written',null,null,'in the original',null,'{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('5acc5f97-8dc2-5677-b433-d2e97ac6f8c3','cdceafde-5346-5600-839c-2f0bf4ff6ce8',3,null,null,'informal','someone whose behaviour , clothing etc is unusual and amusing',null,null,'کسی که رفتار، لباس و غیره اش غیرعادی و سرگرم کننده است','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('d81cb5c6-0eeb-55e0-a241-6fd5723907e3','c68cc56e-017c-581b-8a5a-9666b0deb2dd',1,null,null,'spoken & written','used to say that someone should do something because it is the best or most sensible thing to do',null,null,'باید، سزاوار است (بهتر است)',array['should']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You really ought to quit smoking.","translation":"شما واقعاً باید سیگار را ترک کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000381216.mp3"},{"sentence":"The company ought to be making changes in its marketing strategy.","translation":"شرکت باید در استراتژی بازاریابی خود تغییراتی ایجاد کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558171.mp3"},{"sentence":"What sort of crimes ought the police to concentrate on?","translation":"پلیس باید روی چه نوع جنایاتی تمرکز کند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558173.mp3"},{"sentence":"You were out enjoying yourself when you ought to have been studying.","translation":"زمانی که باید درس می‌خواندید، در حال لذت بردن از خودتان بودید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558174.mp3"}]'::jsonb,4),
('0d4b6abd-9231-586a-b4bb-8b412f698979','c68cc56e-017c-581b-8a5a-9666b0deb2dd',2,null,null,'spoken & written','used to make a suggestion about something you think is a good idea, especially in a social situation',null,null,'برای ارائه پیشنهاد در مورد چیزی که فکر می کنید ایده خوبی است، به خصوص در یک موقعیت اجتماعی استفاده می شود',array['should']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We ought to get together some time soon.","translation":"ما باید به زودی دور هم جمع شویم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558180.mp3"},{"sentence":"You ought to meet him; he’s really nice.","translation":"شما باید او را ملاقات کنید. او واقعاً خوب است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558181.mp3"},{"sentence":"We ought to get her some flowers for her birthday.","translation":"برای تولدش باید برایش گل بیاوریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558182.mp3"},{"sentence":"I ought to call Brian.","translation":"باید به برایان زنگ بزنم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558183.mp3"}]'::jsonb,4),
('2233f7d6-95a3-5910-9d61-a9e8178aeb7f','c68cc56e-017c-581b-8a5a-9666b0deb2dd',3,null,null,'spoken & written','used to say that someone should do something or something should happen, because it is morally right or fair',null,null,'می گفت فلانی باید کاری را انجام دهد یا اتفاقی بیفتد، زیرا از نظر اخلاقی درست یا منصفانه است',array['should']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You ought to be ashamed of yourself.","translation":"باید از خودت خجالت بکشی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000381223.mp3"},{"sentence":"The courts ought to treat black and white defendants in exactly the same way.","translation":"دادگاه ها باید دقیقاً با متهمان سیاه و سفید به همان شیوه رفتار کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558184.mp3"},{"sentence":"Many people felt that America ought not to take part in the war.","translation":"بسیاری از مردم احساس می کردند که آمریکا نباید در جنگ شرکت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558185.mp3"}]'::jsonb,3),
('2a501c65-6b35-51bc-8ab4-78daa3df9775','c68cc56e-017c-581b-8a5a-9666b0deb2dd',4,null,null,'spoken & written','used to say that you think something will probably happen, is probably true etc',null,null,'می گفت که شما فکر می کنید احتمالاً اتفاقی می افتد، احتمالاً درست است و غیره',array['should']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He left two hours ago, so he ought to be there by now.","translation":"او دو ساعت پیش رفت، پس باید تا الان آنجا باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000381233.mp3"},{"sentence":"They ought to win – they’ve trained hard enough.","translation":"آنها باید برنده شوند - آنها به اندازه کافی سخت تمرین کرده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000381234.mp3"},{"sentence":"That ought to be enough potatoes for eight people.","translation":"این باید برای هشت نفر سیب زمینی کافی باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000381235.mp3"},{"sentence":"New technology ought to make this easier.","translation":"فناوری جدید باید این کار را آسان‌تر کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558186.mp3"}]'::jsonb,4),
('76638321-df20-5d94-9c33-d1b635f9f0a4','4554cb4e-8e22-5051-b625-cac7105ac2b6',1,null,null,'spoken & written','to successfully control a feeling or problem that prevents you from achieving something',null,null,'غلبه کردن، چیره شدن (بر ترس)؛ فائق آمدن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He struggled to overcome his shyness.","translation":"او تلاش کرد تا بر کمرویی خود غلبه کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000384958.mp3"},{"sentence":"Her financial problems could no longer be overcome.","translation":"مشکلات مالی او دیگر قابل حل نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001571198.mp3"}]'::jsonb,2),
('fccf8b62-b93c-56db-b207-fcf75e96dce7','4554cb4e-8e22-5051-b625-cac7105ac2b6',2,null,null,'spoken & written','if someone is overcome by smoke or gas , they become extremely sick or unconscious because they breathe it',null,null,'اگر کسی توسط دود یا گاز غلبه کند، به شدت بیمار یا بیهوش می شود زیرا آن را تنفس می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The engineer was working on the freezer when he was overcome by gas.","translation":"مهندس مشغول کار روی فریزر بود که گاز بر او غلبه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001571199.mp3"}]'::jsonb,1),
('97b21db5-3b7b-5cf5-9cc8-459c3e855ef9','4554cb4e-8e22-5051-b625-cac7105ac2b6',3,null,null,'spoken & written','if someone is overcome by emotion , they cannot behave normally because they feel the emotion so strongly',null,null,'اگر احساسی بر کسی غلبه کند، نمی تواند به طور عادی رفتار کند، زیرا این احساس را به شدت احساس می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Charles was overcome with grief.","translation":"چارلز غمگین شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001571206.mp3"}]'::jsonb,1),
('38a07346-b932-5838-aed0-b522446a4bcd','4554cb4e-8e22-5051-b625-cac7105ac2b6',4,null,null,'spoken & written','to fight and win against someone or something',null,null,'جنگیدن و پیروزی در برابر کسی یا چیزی',array['defeat']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Australia overcame the Netherlands 2–1.","translation":"استرالیا ۲–۱ هلند را شکست داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001571207.mp3"}]'::jsonb,1),
('fbf474eb-7a00-553e-815b-c9046e0ffcb6','9cc4da61-c9cd-5af8-a4b0-5264a29dbfd9',1,null,null,'spoken & written','to or in a foreign country that is across the sea',null,null,'به خارج از کشور، در خارج (فراسوی دریا)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Chris is going to work overseas.","translation":"کریس قرار است در خارج از کشور کار کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000386337.mp3"},{"sentence":"Most applications came from overseas.","translation":"اکثر برنامه ها از خارج از کشور آمده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000386338.mp3"}]'::jsonb,2),
('aafa50a3-46d9-5246-8d0b-6e022d456c2d','0e89a8e3-05c5-516d-93a3-a68ab4007bab',1,null,null,'spoken & written','coming from, existing in, or happening in a foreign country that is across the sea',null,null,'از یک کشور خارجی که در آن سوی دریا است، وجود دارد، وجود دارد یا در آن اتفاق می افتد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"overseas students","translation":"دانشجویان خارج از کشور","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000386351.mp3"},{"sentence":"overseas investment","translation":"سرمایه گذاری خارج از کشور","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000386352.mp3"}]'::jsonb,2),
('af8b899f-07d0-5c91-b45f-4c308d5ce5ea','628b30a7-192c-5dd7-ba03-0243a84caabf',1,null,null,'spoken & written','time that you spend working in your job in addition to your normal working hours',null,null,'اضافه‌کار، وقت اضافه (کار)؛ تمدید (بازی)','{}'::text[],'{}'::text[],array['work overtime He''s been working a lot of overtime.','do overtime I did three hours overtime yesterday.','put in overtime (= work overtime ) To earn enough money, he puts in a lot of overtime.','paid/unpaid overtime Many teachers do a lot of unpaid overtime.','unlimited overtime They offered us a bonus and unlimited overtime.','overtime pay/payments/earnings The salary figure does not include overtime pay. If Joe worked 100 hours overtime at time and a half, his overtime payments would be $15,662.','overtime rates (= payments that are set according to a standard scale ) Generous overtime rates are paid for late-night and weekend work.']::text[],'[{"sentence":"six hours’ overtime","translation":"شش ساعت اضافه کاری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000386862.mp3"},{"sentence":"They’re working overtime to get the job finished.","translation":"آنها اضافه کاری می کنند تا کار را تمام کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000386866.mp3"},{"sentence":"He’s been doing a lot of overtime recently.","translation":"او اخیراً اضافه کاری های زیادی انجام می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721952.mp3"},{"sentence":"Many employees work countless hours of unpaid overtime .","translation":"بسیاری از کارمندان ساعات بی شماری اضافه کاری بدون حقوق کار می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001969907.mp3"},{"sentence":"Many of our offices will be working on overtime until the end of the year.","translation":"بسیاری از دفاتر ما تا پایان سال با اضافه کاری کار خواهند کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001969911.mp3"}]'::jsonb,5),
('33f7ec3e-bb62-5f07-9108-00ed3bbf5763','628b30a7-192c-5dd7-ba03-0243a84caabf',2,null,null,'spoken & written','the money that you are paid for working more hours than usual',null,null,'پولی که برای ساعات کاری بیشتر از حد معمول به شما پرداخت می شود','{}'::text[],'{}'::text[],array['work overtime He''s been working a lot of overtime.','do overtime I did three hours overtime yesterday.','put in overtime (= work overtime ) To earn enough money, he puts in a lot of overtime.','paid/unpaid overtime Many teachers do a lot of unpaid overtime.','unlimited overtime They offered us a bonus and unlimited overtime.','overtime pay/payments/earnings The salary figure does not include overtime pay. If Joe worked 100 hours overtime at time and a half, his overtime payments would be $15,662.','overtime rates (= payments that are set according to a standard scale ) Generous overtime rates are paid for late-night and weekend work.']::text[],'[{"sentence":"He earns £450 a week, including overtime.","translation":"او هفته ای 450 پوند با احتساب اضافه کاری دریافت می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000386870.mp3"}]'::jsonb,1),
('e6bedf45-7463-596e-8e42-d71025a15477','628b30a7-192c-5dd7-ba03-0243a84caabf',3,null,null,'spoken & written',null,null,'be working overtime','اضافه‌کار، وقت اضافه (کار)؛ تمدید (بازی)','{}'::text[],'{}'::text[],array['work overtime He''s been working a lot of overtime.','do overtime I did three hours overtime yesterday.','put in overtime (= work overtime ) To earn enough money, he puts in a lot of overtime.','paid/unpaid overtime Many teachers do a lot of unpaid overtime.','unlimited overtime They offered us a bonus and unlimited overtime.','overtime pay/payments/earnings The salary figure does not include overtime pay. If Joe worked 100 hours overtime at time and a half, his overtime payments would be $15,662.','overtime rates (= payments that are set according to a standard scale ) Generous overtime rates are paid for late-night and weekend work.']::text[],'[]'::jsonb,0),
('52d9c080-aef5-55fd-aed1-c0eaa1a10402','628b30a7-192c-5dd7-ba03-0243a84caabf',4,null,null,'spoken & written','a period of time added to the end of a sports game to give one of the two teams a chance to win',null,null,'یک دوره زمانی به پایان یک بازی ورزشی اضافه می شود تا به یکی از دو تیم فرصت برنده شدن بدهد','{}'::text[],'{}'::text[],array['work overtime He''s been working a lot of overtime.','do overtime I did three hours overtime yesterday.','put in overtime (= work overtime ) To earn enough money, he puts in a lot of overtime.','paid/unpaid overtime Many teachers do a lot of unpaid overtime.','unlimited overtime They offered us a bonus and unlimited overtime.','overtime pay/payments/earnings The salary figure does not include overtime pay. If Joe worked 100 hours overtime at time and a half, his overtime payments would be $15,662.','overtime rates (= payments that are set according to a standard scale ) Generous overtime rates are paid for late-night and weekend work.']::text[],'[{"sentence":"Steve Smith scored all nine of the Hawks’ points in overtime.","translation":"استیو اسمیت تمام 9 امتیاز هاکس را در وقت اضافه به دست آورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764906.mp3"}]'::jsonb,1),
('b3f38a69-79ce-50ca-a897-ea346e5bf7c2','1f85a0a6-f314-5d87-bc80-bcf7a408d837',1,null,null,'spoken & written','a painted picture that you put on a wall for people to see','[ countable ]','oil painting','نقاشی، تابلو؛ رنگ‌آمیزی (دیوار)؛ نقاشی (هنر)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a collection of valuable paintings","translation":"مجموعه ای از نقاشی های ارزشمند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537003.mp3"},{"sentence":"There was a large painting of his father on the wall.","translation":"روی دیوار تابلوی بزرگی از پدرش بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001761189.mp3"},{"sentence":"Can you help me hang this painting (= put it on a wall ) ?","translation":"آیا می توانید به من کمک کنید این نقاشی را آویزان کنم (= آن را روی دیوار بگذارم)؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537010.mp3"}]'::jsonb,3),
('900e9745-fe99-5338-9004-4ad94b5d5fc5','1f85a0a6-f314-5d87-bc80-bcf7a408d837',2,null,null,'spoken & written','the act or skill of making a picture, using paints','[ uncountable ]',null,'عمل یا مهارت ساختن یک تصویر با استفاده از رنگ','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Degas’ style of painting","translation":"سبک نقاشی دگا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000391754.mp3"},{"sentence":"the Cubist school of painting (= a particular style used by a group of people )","translation":"مکتب نقاشی کوبیستی (= سبک خاصی که توسط گروهی از مردم استفاده می شود)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537017.mp3"}]'::jsonb,2),
('ad23ec02-99a5-58f9-be68-54c9208ba468','1f85a0a6-f314-5d87-bc80-bcf7a408d837',3,null,null,'spoken & written','the work of covering a wall, house etc with paint','[ uncountable ]',null,'کار پوشاندن دیوار، خانه و غیره با رنگ','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('18017ea7-b719-514b-93c5-a5d2739a6432','a37e76d6-9cdf-59ea-b21d-566c73aff0c4',1,null,null,'spoken & written','the ability to continue waiting or doing something for a long time without becoming angry or anxious',null,null,'شکیبایی، صبر؛ حوصله؛ شکیبایی (جزئی)','{}'::text[],'{}'::text[],array['have the patience to do something He didn''t have the patience to listen to another point of view.','have little/no patience with somebody I''m afraid I have little patience with bureaucrats and their official rules.','lose patience (with somebody) Eventually his family lost patience with him and his irresponsible behaviour.','run out of patience (with somebody) She was wonderful with the children, and never ran out of patience.','try/test/tax somebody''s patience (= make it difficult for someone to continue to be patient ) The guy at the desk was beginning to try my patience.','exhaust somebody''s patience (= make someone lose patience ) He turned away from me, as if I had exhausted his patience.','somebody''s patience is wearing thin (= they are becoming angry ) People''s patience is wearing thin as the queues for visas get longer.','somebody''s patience snaps (= they suddenly show their anger ) Celia''s patience snapped when he dropped a second glass of wine on the carpet.','somebody''s patience is rewarded (= they get what they were hoping and waiting to get ) After two hours, their patience was rewarded and they saw the bird.','great patience Painting by this method requires great patience.','infinite/endless/unlimited patience She was lucky to have a maths teacher with infinite patience.','the patience of Job/a saint (= very great patience ) Those children would try the patience of a saint.']::text[],'[{"sentence":"I wouldn’t have the patience to sit sewing all day.","translation":"حوصله ی خیاطی تمام روز را ندارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584105.mp3"},{"sentence":"a good listener who has infinite patience","translation":"یک شنونده خوب که صبر بی نهایت دارد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584108.mp3"}]'::jsonb,2),
('887861ea-d779-5e81-bf2a-6f9d5b94468f','a37e76d6-9cdf-59ea-b21d-566c73aff0c4',2,null,null,'spoken & written','the ability to accept trouble and other people’s annoying behaviour without complaining or becoming angry',null,null,'توانایی پذیرش مشکل و رفتار آزاردهنده دیگران بدون شکایت یا عصبانی شدن','{}'::text[],'{}'::text[],array['have the patience to do something He didn''t have the patience to listen to another point of view.','have little/no patience with somebody I''m afraid I have little patience with bureaucrats and their official rules.','lose patience (with somebody) Eventually his family lost patience with him and his irresponsible behaviour.','run out of patience (with somebody) She was wonderful with the children, and never ran out of patience.','try/test/tax somebody''s patience (= make it difficult for someone to continue to be patient ) The guy at the desk was beginning to try my patience.','exhaust somebody''s patience (= make someone lose patience ) He turned away from me, as if I had exhausted his patience.','somebody''s patience is wearing thin (= they are becoming angry ) People''s patience is wearing thin as the queues for visas get longer.','somebody''s patience snaps (= they suddenly show their anger ) Celia''s patience snapped when he dropped a second glass of wine on the carpet.','somebody''s patience is rewarded (= they get what they were hoping and waiting to get ) After two hours, their patience was rewarded and they saw the bird.','great patience Painting by this method requires great patience.','infinite/endless/unlimited patience She was lucky to have a maths teacher with infinite patience.','the patience of Job/a saint (= very great patience ) Those children would try the patience of a saint.']::text[],'[{"sentence":"You’ll need patience and understanding if you’re going to be a teacher.","translation":"اگر می خواهید معلم شوید، به صبر و درک نیاز دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584109.mp3"},{"sentence":"She has no patience with time-wasters.","translation":"او هیچ صبر و حوصله ای با اتلاف وقت ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000372971.mp3"},{"sentence":"I’m beginning to lose patience with you people.","translation":"من کم کم صبرم را با شما مردم از دست می دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000372975.mp3"},{"sentence":"It will take time and patience to get these changes accepted.","translation":"پذیرش این تغییرات به زمان و صبر نیاز دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001839726.mp3"},{"sentence":"Celia’s patience suddenly snapped and she told them to shut up.","translation":"صبر سلیا ناگهان شکست و او به آنها گفت که ساکت شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584110.mp3"},{"sentence":"Henry’s negative attitude is beginning to try my patience (= make me lose my patience ) .","translation":"نگرش منفی هنری شروع به امتحان کردن صبر من می کند (= باعث می شود صبرم را از دست بدهم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584116.mp3"}]'::jsonb,6),
('2b3afcfe-7cb5-5b3e-af83-3089ee137abd','a37e76d6-9cdf-59ea-b21d-566c73aff0c4',3,null,null,'spoken & written',null,null,'(have) patience','شکیبایی، صبر؛ حوصله؛ شکیبایی (جزئی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('999bc842-b08e-56e5-a11b-e23ae30438af','a37e76d6-9cdf-59ea-b21d-566c73aff0c4',4,null,null,'spoken & written','a card game for one player',null,null,'یک بازی با ورق برای یک بازیکن','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('0e3fbd9f-6c76-53ec-82b8-d9a8029cfe00','68c3bf1f-8c4a-5678-bb04-abe51d68ee26',1,null,null,'spoken & written','a peaceful time, place, or situation is quiet and calm without any worry or excitement',null,null,'آرام، صلح‌آمیز؛ خوش‌گذرانه (زمان)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We had a peaceful afternoon without the children.","translation":"بعدازظهر آرامی را بدون بچه ها سپری کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000378143.mp3"},{"sentence":"It’s very peaceful out here in the woods.","translation":"اینجا در جنگل بسیار آرام است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001665780.mp3"}]'::jsonb,2),
('059b842e-aaed-549d-b096-fa1948d19497','68c3bf1f-8c4a-5678-bb04-abe51d68ee26',2,null,null,'spoken & written','not involving war, fighting , or violence',null,null,'شامل جنگ، جنگ، یا خشونت نمی شود','{}'::text[],'{}'::text[],array['a peaceful protest/demonstration 5,000 students began a peaceful protest which turned into a violent confrontation with police.','a peaceful solution/resolution/settlement The authorities want a peaceful solution to the hostage crisis.','peaceful coexistence (= when people live together without fighting or arguing ) Blacks and whites lived in peaceful coexistence.','a peaceful transition (= a peaceful change from one system to another ) They hope to achieve a peaceful transition to democracy.','by/through peaceful means We must redistribute power in this country by peaceful means.','for peaceful purposes A Foreign Ministry spokesman stressed that the nuclear programme is for peaceful purposes.']::text[],'[{"sentence":"There was a large but peaceful demonstration outside the US Embassy.","translation":"تظاهرات بزرگ اما مسالمت آمیزی در مقابل سفارت آمریکا برگزار شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001765526.mp3"},{"sentence":"We must try to find a peaceful solution to the conflict.","translation":"ما باید تلاش کنیم راه حلی مسالمت آمیز برای درگیری پیدا کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001665786.mp3"},{"sentence":"a political change achieved by peaceful and democratic means","translation":"یک تغییر سیاسی که با ابزارهای مسالمت آمیز و دموکراتیک به دست می آید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001665789.mp3"},{"sentence":"the use of nuclear power for peaceful purposes","translation":"استفاده از انرژی هسته ای برای اهداف صلح آمیز","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001182.mp3"},{"sentence":"The countries in Europe have established a peaceful co-existence (= they exist together without fighting ) .","translation":"کشورهای اروپایی یک همزیستی مسالمت آمیز برقرار کرده اند (= بدون جنگ با هم وجود دارند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001839754.mp3"}]'::jsonb,5),
('9046e3ae-0a30-5a4f-8f61-085bf959bf8f','68c3bf1f-8c4a-5678-bb04-abe51d68ee26',3,null,null,'spoken & written','peaceful people do not like violence and do not behave in a violent way',null,null,'افراد صلح جو خشونت را دوست ندارند و رفتار خشونت آمیز ندارند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a noisy but peaceful group of demonstrators","translation":"گروهی پر سر و صدا اما صلح آمیز از تظاهرکنندگان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000378152.mp3"}]'::jsonb,1),
('f661c624-e7d2-5c3e-9bb4-82012cf1b264','c14ddac8-4615-5f8b-ab50-63ec977667de',1,null,null,'written','to understand or think of something or someone in a particular way',null,null,'درک کردن، دریافت کردن (به‌طور خاص)؛ پنداشتن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Even as a young woman she had been perceived as a future chief executive.","translation":"حتی به عنوان یک زن جوان، او به عنوان یک مدیر اجرایی آینده تلقی می شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349257.mp3"},{"sentence":"Often what is perceived to be aggression is simply fear.","translation":"اغلب آنچه به عنوان پرخاشگری در نظر گرفته می شود، صرفاً ترس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349260.mp3"},{"sentence":"Children who do badly in school tests often perceive themselves to be failures.","translation":"کودکانی که در آزمون های مدرسه ضعیف عمل می کنند، اغلب خود را شکست خورده می دانند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001765787.mp3"}]'::jsonb,3),
('b945e85a-bc64-5dc0-8d0e-82103cbd4063','c14ddac8-4615-5f8b-ab50-63ec977667de',2,null,null,'formal','to notice , see, or recognize something',null,null,'متوجه شدن، دیدن یا تشخیص چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"That morning, he perceived a change in Franca’s mood.","translation":"آن روز صبح، او تغییری در خلق و خوی فرانکا احساس کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349267.mp3"},{"sentence":"Cats are not able to perceive colour.","translation":"گربه ها قادر به درک رنگ نیستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537799.mp3"},{"sentence":"He perceived that there was no other way out of the crisis.","translation":"او دریافت که راه دیگری برای خروج از بحران وجود ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001765793.mp3"}]'::jsonb,3),
('87194aca-22d3-5ecd-a34a-5dca4963b93e','69ff9939-5724-5d2f-b9e7-3e88cbd9e2f6',1,null,null,'spoken & written','belonging or relating to one particular person, rather than to other people or to people in general','[ only before noun ]',null,'شخصی، خصوصی؛ شخصی (دستور)؛ متعلق به (خود)','{}'::text[],'{}'::text[],array['somebody’s personal view/opinion My personal opinion is that the project was started too soon.','somebody’s personal possessions/belongings/property All personal belongings should be clearly marked with the owner’s name.','somebody’s personal effects (formal) (= small possessions, clothing etc ) After his suicide, his mother received his personal effects.','personal taste/preference What you plant in your garden is ultimately a matter of personal preference.','personal qualities They stress the importance of a teacher’s personal qualities.','personal experience I have had personal experience of unemployment.','a personal relationship It’s important to establish a good personal relationship with the voters.','a personal interest in something He took a personal interest in the case.','for (your) personal use He bought a computer for his personal use.','on a personal level (= used when giving your own opinion rather than the opinion of the organization you represent ) On a personal level, it’s been a very positive experience.']::text[],'[{"sentence":"My personal view is that we shouldn’t offer him the job.","translation":"نظر شخصی من این است که نباید به او پیشنهاد کار بدهیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766610.mp3"},{"sentence":"Style and colour are a matter of personal taste .","translation":"سبک و رنگ بستگی به سلیقه شخصی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584458.mp3"},{"sentence":"She took full personal responsibility for all the arrangements.","translation":"او مسئولیت کامل تمام ترتیبات را به عهده گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766611.mp3"},{"sentence":"When I went to her room all her personal belongings had gone.","translation":"وقتی به اتاقش رفتم تمام وسایل شخصی اش رفته بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584472.mp3"},{"sentence":"After Nelson’s death, his mother received his personal effects .","translation":"پس از مرگ نلسون، مادرش وسایل شخصی او را دریافت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00648.mp3"},{"sentence":"I know from personal experience that you can’t trust Trevor.","translation":"من از تجربه شخصی می دانم که نمی توانید به تروور اعتماد کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00649.mp3"},{"sentence":"the personal qualities needed to be successful in business","translation":"ویژگی های شخصی مورد نیاز برای موفقیت در تجارت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942253.mp3"},{"sentence":"The car is for personal use only.","translation":"ماشین فقط برای استفاده شخصی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942257.mp3"},{"sentence":"On a personal level he felt sympathy for them, but he had a job to do.","translation":"در سطح شخصی او نسبت به آنها احساس همدردی می کرد، اما کاری برای انجام دادن داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942261.mp3"},{"sentence":"celebrities with their own personal trainer","translation":"افراد مشهور با مربی شخصی خود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942264.mp3"}]'::jsonb,10),
('d1f3a66d-9a8b-534f-9536-848bbd9ec1cc','69ff9939-5724-5d2f-b9e7-3e88cbd9e2f6',2,null,null,'spoken & written','relating to the private areas of your life',null,null,'مربوط به بخش های خصوصی زندگی شما','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I don’t answer questions about my personal life .","translation":"من به سوالات مربوط به زندگی شخصی ام پاسخ نمی دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584484.mp3"},{"sentence":"May I ask you a personal question ?","translation":"ممکن است یک سوال شخصی از شما بپرسم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766612.mp3"},{"sentence":"the records will include other personal details such as nationality, date of birth and address","translation":"سوابق شامل سایر مشخصات شخصی مانند ملیت، تاریخ تولد و آدرس خواهد بود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942271.mp3"},{"sentence":"He’s got a few personal problems at the moment.","translation":"او در حال حاضر چند مشکل شخصی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766613.mp3"},{"sentence":"The envelope was marked ‘Personal and Confidential’.","translation":"روی پاکت علامت گذاری شده بود \"شخصی و محرمانه\".","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766614.mp3"},{"sentence":"We’re not allowed to make personal phone calls at work.","translation":"ما مجاز به برقراری تماس تلفنی شخصی در محل کار نیستیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766615.mp3"}]'::jsonb,6),
('12861e84-9a20-5174-9814-89665e96fb64','69ff9939-5724-5d2f-b9e7-3e88cbd9e2f6',3,null,null,'spoken & written','involving rude or upsetting criticism of someone',null,null,'شامل انتقاد بی ادبانه یا ناراحت کننده از کسی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s unprofessional to make such personal remarks.","translation":"بیان چنین اظهارات شخصی غیرحرفه ای است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766616.mp3"},{"sentence":"a bitter personal attack on the president","translation":"حمله شخصی تلخ به رئیس جمهور","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766617.mp3"},{"sentence":"There’s no need to get personal !","translation":"نیازی به شخصی نیست!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584505.mp3"},{"sentence":"It’s nothing personal, I just have to go home now.","translation":"این چیز شخصی نیست، فقط باید الان بروم خانه.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000353217.mp3"}]'::jsonb,4),
('a88e1c4f-4f38-5e11-aa88-08cdfc9c3ede','69ff9939-5724-5d2f-b9e7-3e88cbd9e2f6',4,null,null,'spoken & written','if you give something your personal care or attention , you deal with it yourself instead of asking someone else to do it',null,null,'اگر به چیزی توجه یا مراقبت شخصی خود را بدهید، به جای اینکه از شخص دیگری بخواهید آن را انجام دهد، خودتان با آن برخورد می کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Small companies can devote more personal attention to each project.","translation":"شرکت های کوچک می توانند توجه شخصی بیشتری را به هر پروژه اختصاص دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766618.mp3"},{"sentence":"As you get promoted in a firm you lose that personal contact (= meeting and dealing with people yourself ) .","translation":"وقتی در یک شرکت ارتقا پیدا می کنید، آن تماس شخصی (= ملاقات و برخورد با افراد خودتان) را از دست می دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000353175.mp3"}]'::jsonb,2),
