('303a25fe-da87-5ef3-8f57-ff43d6bcda08','298f1984-3c7f-506c-b257-71f9f46f9031',1,null,null,'spoken & written','to make someone decide to do something, especially by giving them reasons why they should do it, or asking them many times to do it',null,null,'قانع کردن، متقاعد ساختن (با دلیل)؛ وادار کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I finally managed to persuade her to go out for a drink with me.","translation":"بالاخره توانستم او را متقاعد کنم که با من برای نوشیدنی بیرون برود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584653.mp3"},{"sentence":"Don’t let yourself be persuaded into buying things you don’t want.","translation":"اجازه ندهید که متقاعد شوید چیزهایی را که نمی خواهید بخرید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584656.mp3"},{"sentence":"I’m trying to persuade your dad to buy some shares.","translation":"من سعی می کنم پدرت را متقاعد کنم که چند سهم بخرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584659.mp3"},{"sentence":"Leo wouldn’t agree, despite our efforts to persuade him.","translation":"لئو با وجود تلاش های ما برای متقاعد کردن او موافقت نکرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584662.mp3"},{"sentence":"He took a lot of persuading to come out of retirement (= it was hard to persuade him ) .","translation":"او برای بیرون آمدن از بازنشستگی متقاعد کننده بسیار گرفت (= اقناع او سخت بود ) .","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766643.mp3"},{"sentence":"He was fairly easily persuaded .","translation":"او به راحتی متقاعد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584663.mp3"}]'::jsonb,6),
('26286432-e125-57e7-80ac-e43535bb3f60','298f1984-3c7f-506c-b257-71f9f46f9031',2,null,null,'spoken & written','to make someone believe something or feel sure about something',null,null,'وادار کردن کسی چیزی را باور کند یا از چیزی مطمئن باشد',array['convince']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I am not persuaded by these arguments.","translation":"من با این استدلال ها قانع نمی شوم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000353684.mp3"},{"sentence":"She’ll only take me back if I can persuade her that I’ve changed.","translation":"او تنها در صورتی مرا پس می‌گیرد که بتوانم او را متقاعد کنم که تغییر کرده‌ام.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584669.mp3"},{"sentence":"McFadden must persuade the jury of her innocence.","translation":"مک فادن باید هیئت منصفه را در مورد بی گناهی خود متقاعد کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584672.mp3"}]'::jsonb,3),
('ded8a922-e20c-541f-8fb2-a41221af5b5d','e29e7bb7-f6d5-5505-9ef1-1f77432a545d',1,'body not mind','بدن نه ذهن','spoken & written','related to someone’s body rather than their mind or emotions',null,null,'بدنی، جسمی؛ فیزیکی (کار)؛ مادی (فرد)','{}'::text[],'{}'::text[],array['physical activity We all know about the health benefits of physical activity.','physical contact There shall be no intentional physical contact between teams.','physical abuse/violence He had suffered physical abuse at the hands of his parents.','somebody’s physical appearance Describe his physical appearance.','physical pain She bravely endured great physical pain.','physical strength The murder could have been committed only by a man of enormous physical strength.','physical fitness You need to work on your physical fitness.','a physical disability (= condition that makes it difficult for someone to use a part of their body properly ) From birth he has suffered from severe physical disabilities.','a physical defect (= a physical fault, especially one that only affects the appearance ) Most babies are born without physical defects.']::text[],'[{"sentence":"She was in constant physical pain.","translation":"او مدام درد جسمی داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001566279.mp3"},{"sentence":"the physical and emotional needs of young adults","translation":"نیازهای جسمی و عاطفی جوانان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001566280.mp3"},{"sentence":"people with severe physical disabilities","translation":"افراد دارای ناتوانی جسمی شدید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001768855.mp3"},{"sentence":"Don’t be put off by his physical appearance .","translation":"ظاهر فیزیکی او را ناامید نکنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001566281.mp3"},{"sentence":"He was obsessed with physical fitness .","translation":"او به آمادگی جسمانی علاقه زیادی داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001566288.mp3"}]'::jsonb,5),
