('6a27214c-61d7-5586-8550-76b5b0aef866','b629760b-4d4e-57bb-b110-53b0e3ee67e7',1,null,null,'spoken & written','enjoyable or attractive and making you feel happy',null,null,'خوش‌آمد، مطبوع؛ دلپذیر (حس)',array['nice']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It had been a pleasant evening.","translation":"عصر دلپذیری بود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000339448.mp3"},{"sentence":"the pleasant climate of Southern California","translation":"آب و هوای دلپذیر کالیفرنیای جنوبی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560612.mp3"},{"sentence":"The restaurant was large and pleasant.","translation":"رستوران بزرگ و دلنشینی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000339450.mp3"},{"sentence":"Kate! What a pleasant surprise !","translation":"کیت! چه سورپرایز دلپذیری!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000339449.mp3"},{"sentence":"It was pleasant to sit in a sidewalk cafe and watch people pass.","translation":"نشستن در یک کافه پیاده رو و تماشای عبور مردم لذت بخش بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560616.mp3"}]'::jsonb,5),
