('0507dd17-4a42-508f-bea3-890c7a10e70d','b7eabb12-fb3f-5c5b-ad93-851263607cb3',11,'race/competition','مسابقه/مسابقه','spoken & written','the place of someone or something in a race or competition in relation to the other people or things','[ countable, uncountable ]',null,'جایگاه کسی یا چیزی در یک مسابقه یا مسابقه در رابطه با افراد یا چیزهای دیگر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Alesi finished in third position .","translation":"آلسی در جایگاه سوم قرار گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000311409.mp3"}]'::jsonb,1),
