('311321c0-493a-5242-bccd-ad5e4172ac40','b7eabb12-fb3f-5c5b-ad93-851263607cb3',14,'army','ارتش','spoken & written','a place where an army has put soldiers, guns etc','[ countable usually plural ]',null,'جایی که ارتش سرباز، تفنگ و غیره را در آن قرار داده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an attack on the enemy positions","translation":"حمله به مواضع دشمن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000311435.mp3"}]'::jsonb,1),
('7dede1f8-42e1-51a8-b343-0cccee5b3950','7d724885-c93f-536e-a651-b408c3682be0',1,null,null,'spoken & written','to carefully put something in a particular position',null,null,'با دقت چیزی را در موقعیتی خاص قرار دادن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Position the cursor before the letter you want to delete.","translation":"مکان نما را قبل از حرفی که می خواهید حذف کنید قرار دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000311484.mp3"},{"sentence":"I positioned myself where I could see the door.","translation":"جایی قرار گرفتم که بتوانم در را ببینم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576484.mp3"}]'::jsonb,2),
