('ee43a47c-3895-564e-8ed5-44ed21d321e2','79efc1d2-3ef0-53d9-8fb0-8c39415b5e69',1,'attitude','نگرش','spoken & written','if you are positive about things, you are hopeful and confident , and think about what is good in a situation rather than what is bad',null,null,'مثبت، خوش‌بین؛ مطمئن (پاسخ)؛ مثبت (عدد)','{}'::text[],'{}'::text[],array['a positive attitude/outlook Having a positive attitude makes life so much better.','a positive approach This is just the positive approach that the school needs.','a positive view He takes a fairly positive view of the future.','a positive thought Think positive thoughts.','positive thinking Many people believe that positive thinking can help your recovery from serious illnesses.','think positive (= think positive thoughts ) Cheer up and think positive.']::text[],'[{"sentence":"You’ve got to be more positive about your work.","translation":"شما باید نسبت به کار خود مثبت اندیش باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576497.mp3"},{"sentence":"She’s got a really positive attitude to life.","translation":"او نگرش بسیار مثبتی به زندگی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000311523.mp3"},{"sentence":"the power of positive thinking","translation":"قدرت مثبت اندیشی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576502.mp3"},{"sentence":"‘ Think positive !’ she advised herself.","translation":"او به خودش توصیه کرد: «مثبت فکر کن!»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576505.mp3"}]'::jsonb,4),
('a804ac6e-d99c-5785-b74d-15ae86832c8b','79efc1d2-3ef0-53d9-8fb0-8c39415b5e69',2,'good thing','چیز خوب','spoken & written','good or useful',null,null,'خوب یا مفید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"At least something positive has come out of the situation.","translation":"حداقل یک چیز مثبت از این وضعیت بیرون آمده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007788.mp3"},{"sentence":"Write down all the positive things about your life.","translation":"همه چیزهای مثبت زندگی خود را یادداشت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007792.mp3"},{"sentence":"The rural environment was having a positive effect on the children’s health.","translation":"محیط روستایی تأثیر مثبتی بر سلامت کودکان داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007796.mp3"},{"sentence":"It’s been a very positive experience for her.","translation":"این یک تجربه بسیار مثبت برای او بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007800.mp3"},{"sentence":"TV can be a positive influence .","translation":"تلویزیون می تواند تأثیر مثبتی داشته باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007804.mp3"},{"sentence":"the positive contribution to the community made by many older people","translation":"کمک مثبت بسیاری از افراد مسن به جامعه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007808.mp3"},{"sentence":"It’s been a difficult time but, on the positive side , I feel physically fine.","translation":"دوران سختی بود، اما از جنبه مثبت، از نظر بدنی احساس خوبی دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007814.mp3"},{"sentence":"Women should be portrayed in a more positive light .","translation":"زنان باید با دید مثبت تری به تصویر کشیده شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007818.mp3"}]'::jsonb,8),
('86cef460-ad2d-53f4-80d2-2085b57b439a','79efc1d2-3ef0-53d9-8fb0-8c39415b5e69',3,'action','اقدام','spoken & written','if you take positive action, you do something definite in order to try to achieve something',null,null,'اگر اقدام مثبتی انجام دهید، برای تلاش برای رسیدن به چیزی، کار مشخصی انجام می دهید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We need to take positive steps to improve the situation of families in poverty.","translation":"باید برای بهبود وضعیت خانواده های فقیر گام های مثبتی برداریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576536.mp3"},{"sentence":"Positive action was required.","translation":"اقدام مثبت لازم بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576540.mp3"},{"sentence":"It’s a relief to know that something positive is being done.","translation":"دانستن اینکه کار مثبتی در حال انجام است، آرامش بخش است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576543.mp3"}]'::jsonb,3),
('fd1cb30b-94d9-5b94-9291-d8a4b3e6ab7b','79efc1d2-3ef0-53d9-8fb0-8c39415b5e69',4,'support','پشتیبانی کنید','spoken & written','expressing support, agreement, or approval',null,null,'ابراز حمایت، موافقت یا تایید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The response we’ve had from the public has been very positive.","translation":"پاسخی که ما از مردم داشتیم بسیار مثبت بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000311542.mp3"},{"sentence":"We’ve had a lot of positive feedback from the people of this city.","translation":"ما بازخوردهای مثبت زیادی از مردم این شهر داشته ایم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576553.mp3"},{"sentence":"Most people have been very positive about the show.","translation":"اکثر مردم نسبت به نمایش بسیار مثبت بوده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576559.mp3"}]'::jsonb,3),
('1bc646fd-3125-557e-8dcf-2d82d6180f12','79efc1d2-3ef0-53d9-8fb0-8c39415b5e69',5,'sure','مطمئن','spoken & written','very sure, with no doubt at all that something is right or true','[ not before noun ]',null,'بسیار مطمئن، بدون هیچ شکی که چیزی درست یا واقعی است',array['certain']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Are you absolutely positive you locked the door?","translation":"آیا کاملاً مطمئن هستید که در را قفل کرده اید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576568.mp3"},{"sentence":"‘Are you sure about that?’ ‘Positive.’","translation":"«در مورد آن مطمئنی؟» «مثبت است.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576572.mp3"}]'::jsonb,2),
