('e4d95d11-6a66-511a-94ca-27068459e80a','f68575f4-1db9-5744-ae4f-61d316ce5a29',1,null,null,'spoken & written','a quality or feature that is good or useful',null,null,'کیفیت یا ویژگی که خوب یا مفید است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You can find positives in any situation.","translation":"در هر شرایطی می توانید نکات مثبت را پیدا کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576284.mp3"},{"sentence":"Always emphasise the positive .","translation":"همیشه بر موارد مثبت تاکید کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576285.mp3"}]'::jsonb,2),
('83f0596d-14b2-5609-bf6f-c66e291eee28','395245b0-d954-5c00-ab17-655da7a2573a',1,null,null,'spoken & written','if something is possible, it can be done or achieved',null,null,'ممکن، شدنی؛ قابل‌تصور (فرد)','{}'::text[],'{}'::text[],array['it is possible to do something From the hilltop it was possible to see the sea.','make it possible to do something Medical advances have made it possible to keep more patients alive.','if possible ( also if at all possible ) If possible, take light exercise first thing in the morning.','where/wherever/whenever possible Choose wholemeal varieties of flour and pasta, where possible.','do everything possible We must do everything possible to limit our impact on the Earth''s environment.','in every way possible The company helped promote the scheme in every way possible.','perfectly/quite possible (= definitely possible ) Combining a family with a career is perfectly possible .','theoretically possible (= possible in theory, but difficult and unlikely ) It is theoretically possible for all students to get full marks.','technically possible (= possible with the technology available ) Amendments to software may be technically possible, but are inadvisable.','humanly possible (= possible for anyone ) It is not humanly possible to work for more than fifteen hours a day.']::text[],'[{"sentence":"Is it possible to get tickets for the game?","translation":"آیا امکان تهیه بلیط بازی وجود دارد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007848.mp3"},{"sentence":"It might be possible for the documents to be sent over.","translation":"ممکن است امکان ارسال مدارک وجود داشته باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007851.mp3"},{"sentence":"Computer technology makes it possible for many people to work from home.","translation":"فناوری رایانه این امکان را برای بسیاری از افراد فراهم می کند که از خانه کار کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007856.mp3"},{"sentence":"I want to avoid the rush hour traffic if possible .","translation":"من می خواهم در صورت امکان از ترافیک ساعت شلوغی جلوگیری کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007862.mp3"},{"sentence":"I walk or use public transport whenever possible .","translation":"تا حد امکان پیاده روی می کنم یا از وسایل حمل و نقل عمومی استفاده می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007866.mp3"},{"sentence":"We are doing everything possible to track down the killer.","translation":"ما تمام تلاش خود را برای ردیابی قاتل انجام می دهیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007870.mp3"},{"sentence":"Our staff will help you in every way possible .","translation":"کارکنان ما به هر نحو ممکن به شما کمک خواهند کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007874.mp3"},{"sentence":"Even if it were technically possible , we do not have the money to do it.","translation":"حتی اگر از نظر فنی امکان پذیر بود، ما پول انجام آن را نداریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007878.mp3"},{"sentence":"She decided to stay as far away from him as was humanly possible .","translation":"او تصمیم گرفت تا جایی که ممکن است از او دور بماند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002007882.mp3"}]'::jsonb,9),
