('cbd0b5b1-06cf-5c11-b8ee-7c711043ab51','b7d2400a-82d8-5d05-81e2-1d955765aab1',1,null,null,'spoken & written','someone or something that might be suitable or acceptable for a particular purpose',null,null,'کسی یا چیزی که ممکن است برای یک هدف خاص مناسب یا قابل قبول باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Frank’s a possible for the job.","translation":"فرانک برای این کار ممکن است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000312751.mp3"}]'::jsonb,1),
('fdc05f79-410f-5e1a-99ea-ab5c2413a41e','976c7a02-581b-5ced-bbba-891ad44974a1',1,null,null,'spoken & written','used when saying that something may be true or likely , although you are not completely certain',null,null,'شاید، ممکن است؛ به‌طور ممکن (احتمال)',array['perhaps','maybe']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This last task is possibly the most difficult.","translation":"این آخرین کار احتمالاً سخت ترین است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576801.mp3"},{"sentence":"It will take three weeks, possibly longer.","translation":"سه هفته طول می کشد، احتمالاً بیشتر.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576802.mp3"},{"sentence":"‘Will you be here tomorrow?’ ‘Possibly.’","translation":"«فردا اینجا خواهی بود؟» «احتمالاً.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000312764.mp3"},{"sentence":"‘Was it murder?’ ‘ Quite possibly (= it is very likely ) .’","translation":"\"آیا این قتل بود؟\" \"به احتمال زیاد (= بسیار محتمل است) .\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000312769.mp3"}]'::jsonb,4),
('ee30eb44-b357-5834-908c-a5abd721b8a7','976c7a02-581b-5ced-bbba-891ad44974a1',2,null,null,'spoken','used to emphasize that you are very surprised or shocked by something, or you cannot understand it',null,null,'برای تأکید بر این که از چیزی بسیار شگفت زده یا شوکه شده اید یا نمی توانید آن را درک کنید استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"How could anyone possibly do such a thing?","translation":"چگونه ممکن است کسی چنین کاری انجام دهد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000312783.mp3"}]'::jsonb,1),
('ea8338b2-c2f8-5539-918a-f32621adf040','976c7a02-581b-5ced-bbba-891ad44974a1',3,null,null,'spoken & written',null,null,'could/can you possibly','شاید، ممکن است؛ به‌طور ممکن (احتمال)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ac4795ad-17ac-52ba-9eb7-86031e6909f2','976c7a02-581b-5ced-bbba-891ad44974a1',4,null,null,'spoken & written','used to emphasize that someone will do or has done everything they can to help or to achieve something',null,null,'برای تأکید بر اینکه کسی هر کاری که می تواند برای کمک یا رسیدن به چیزی انجام می دهد یا انجام داده است استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We shall be contributing as much as we possibly can to the campaign.","translation":"ما تا جایی که بتوانیم در کمپین مشارکت خواهیم کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576808.mp3"},{"sentence":"Doctors did everything they possibly could to save his life.","translation":"پزشکان هر کاری که ممکن بود برای نجات جان او انجام دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576814.mp3"}]'::jsonb,2),
('38daa5d9-3d9d-5dbc-a8b2-b03d71f201d5','976c7a02-581b-5ced-bbba-891ad44974a1',5,null,null,'spoken & written','used to emphasize that you cannot do something, or that something cannot or could not happen or be done',null,null,'برای تأکید بر این که شما نمی توانید کاری را انجام دهید یا چیزی نمی تواند یا نمی تواند اتفاق بیفتد یا انجام شود استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I can’t possibly allow you to go home in this weather.","translation":"من نمی توانم به شما اجازه دهم در این هوا به خانه بروید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000312794.mp3"},{"sentence":"She couldn’t possibly have heard what was said.","translation":"او احتمالاً نمی توانست آنچه گفته شده را بشنود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001576822.mp3"}]'::jsonb,2),
('9689e334-de73-50d3-a64e-11696272c08f','495040db-acad-50b1-bc8e-f789c60db688',1,'important','مهم است','spoken & written','a powerful person, organization, group etc is able to control and influence events and other people’s actions',null,null,'توانمند، نیرومند؛ اثرگذار (گفتار)؛ سنگین (کوره)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was one of the most powerful men in Bohemia.","translation":"او یکی از قدرتمندترین مردان بوهم بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317002.mp3"},{"sentence":"a very influential and powerful family","translation":"خانواده ای بسیار تاثیرگذار و قدرتمند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317001.mp3"},{"sentence":"rich and powerful nations","translation":"کشورهای ثروتمند و قدرتمند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567915.mp3"}]'::jsonb,3),
('b1253f8a-c282-5617-b76f-20919d8e99ec','495040db-acad-50b1-bc8e-f789c60db688',2,'speech/film etc','سخنرانی/فیلم و غیره','spoken & written','having a strong effect on someone’s feelings or opinions',null,null,'تأثیر شدیدی بر احساسات یا عقاید کسی دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a powerful speech","translation":"یک سخنرانی قدرتمند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317008.mp3"},{"sentence":"Good teamwork is a powerful tool (= very effective method ) for effective management.","translation":"کار تیمی خوب ابزاری قدرتمند (= روش بسیار مؤثر) برای مدیریت مؤثر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567916.mp3"}]'::jsonb,2),
('3dc2be6e-366b-5b97-bed4-afd6eb7037bc','495040db-acad-50b1-bc8e-f789c60db688',3,'feeling/effect','احساس/اثر','spoken & written','a powerful feeling or effect is very strong or great',null,null,'یک احساس یا اثر قدرتمند بسیار قوی یا عالی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Immigrants have had a powerful influence on the local culture.","translation":"مهاجران تأثیر قدرتمندی بر فرهنگ محلی داشته اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317009.mp3"},{"sentence":"a powerful sense of tradition","translation":"حس قدرتمند سنت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317007.mp3"}]'::jsonb,2),
('313a68f8-5521-5c25-8dbe-c973202c6bc9','495040db-acad-50b1-bc8e-f789c60db688',4,'machine/weapon etc','ماشین / سلاح و غیره','spoken & written','a powerful machine, engine , weapon etc is very effective and can do a lot',null,null,'یک ماشین قدرتمند، موتور، سلاح و غیره بسیار موثر است و می تواند کارهای زیادی انجام دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a new generation of more powerful PCs","translation":"نسل جدیدی از رایانه های شخصی قدرتمندتر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317017.mp3"},{"sentence":"a machine that is immensely powerful","translation":"ماشینی که فوق العاده قدرتمند است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567927.mp3"},{"sentence":"a powerful 24-valve engine","translation":"یک موتور قدرتمند 24 سوپاپ","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317018.mp3"},{"sentence":"a powerful telescope","translation":"یک تلسکوپ قدرتمند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567931.mp3"}]'::jsonb,4),
('25a31f7a-1a3f-5ec6-b5fe-a2f74b4a440b','495040db-acad-50b1-bc8e-f789c60db688',5,'physically strong','از نظر بدنی قوی','spoken & written','physically strong',null,null,'از نظر بدنی قوی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Jed was a powerful, well-built man.","translation":"جید مردی قدرتمند و خوش اندام بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317029.mp3"},{"sentence":"The females are smaller and less powerful than the males.","translation":"ماده ها کوچکتر و قدرت کمتری نسبت به نرها دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317030.mp3"}]'::jsonb,2),
('02cb6e32-2327-5efd-b53e-ab23221437d8','495040db-acad-50b1-bc8e-f789c60db688',6,'a lot of force','نیروی زیادی','spoken & written','a powerful blow , explosion etc has a lot of force',null,null,'یک ضربه قوی، انفجار و غیره دارای قدرت زیادی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an explosion ten times more powerful than the Hiroshima bomb","translation":"انفجاری ده برابر قوی تر از بمب هیروشیما","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317044.mp3"},{"sentence":"a powerful right-foot shot on goal","translation":"یک شوت قدرتمند پای راست روی دروازه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317045.mp3"},{"sentence":"winds powerful enough to uproot trees","translation":"بادها به اندازه کافی قوی هستند که درختان را ریشه کن کنند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567932.mp3"}]'::jsonb,3),
('981c7fdf-8828-5648-abfd-005315a7f422','495040db-acad-50b1-bc8e-f789c60db688',7,'medicine','دارو','spoken & written','a powerful medicine or drug has a very strong effect on your body',null,null,'یک دارو یا داروی قوی تأثیر بسیار قوی بر بدن شما دارد','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('dcd838dc-88e2-5137-9bcc-b480182b3300','495040db-acad-50b1-bc8e-f789c60db688',8,'team/army etc','تیم / ارتش و غیره','spoken & written','a powerful team, army etc is very strong and can easily defeat other teams or armies',null,null,'یک تیم قدرتمند، ارتش و غیره بسیار قوی است و به راحتی می تواند تیم ها یا ارتش های دیگر را شکست دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a powerful fighting force","translation":"یک نیروی جنگی قدرتمند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317035.mp3"}]'::jsonb,1),
('b42bd241-069c-57d4-8333-f776820cfc33','495040db-acad-50b1-bc8e-f789c60db688',9,'quality','کیفیت','spoken & written','very strong, bright , loud etc',null,null,'بسیار قوی، روشن، با صدای بلند و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a powerful singing voice","translation":"صدای خوانندگی قدرتمند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317040.mp3"},{"sentence":"the powerful headlights","translation":"چراغ های جلو قدرتمند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567937.mp3"}]'::jsonb,2),
('81d38d58-a6d0-588e-8576-2625fd874fe5','8d194860-514a-5555-8256-56c79d3c964f',1,'a skill','یک مهارت','spoken & written','when you do a particular thing, often regularly, in order to improve your skill at it','[ countable, uncountable ]',null,'تمرین، مشق؛ عمل (پزشکی)؛ عرف، رویه','{}'::text[],'{}'::text[],array['do practice Have you done your piano practice?','take practice American English (= do practice ) If he’d done badly, he’d go out and take extra batting practice.','have some/more etc practice (= do practice ) I’m not a very good dancer. I haven’t had enough practice.','get some practice You must get as much practice as possible before the competition.','need practice She needs more practice.','something takes practice (= you can only learn to do it well by practising ) Writing well takes practice.','football/basketball etc practice Dale was at football practice.','piano/cello etc practice I’ve got to do my cello practice.','batting/catching etc practice We''d better do a bit of batting practice before the game.','choir practice There''s choir practice on Tuesday evening.','band practice Have you got band practice tonight?','target practice (= practice shooting at something ) The area is used by the army for target practice.','teaching practice You have to do three months of teaching practice before you qualify.']::text[],'[{"sentence":"It takes hours of practice to learn to play the guitar.","translation":"یادگیری نواختن گیتار ساعت ها تمرین نیاز دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317475.mp3"},{"sentence":"With a little more practice you should be able to pass your test.","translation":"با کمی تمرین بیشتر باید بتوانید آزمون خود را با موفقیت پشت سر بگذارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317476.mp3"},{"sentence":"We have choir practice on Tuesday evening.","translation":"سه شنبه عصر تمرین گروه کر داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317481.mp3"},{"sentence":"Schumacher crashed out in practice for the Australian grand prix.","translation":"شوماخر در تمرین برای گرندپری استرالیا سقوط کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317482.mp3"},{"sentence":"John’s at baseball practice.","translation":"جان در تمرین بیسبال","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766029.mp3"}]'::jsonb,5),
