('ca16b1b4-7d06-550a-8e8c-2255f300a199','fd1821d3-c558-5e28-991c-af5352a2d458',1,null,null,'spoken & written','to do an activity , often regularly, in order to improve your skill or to prepare for a test','[ intransitive, transitive ]',null,'تمرین کردن، مشق کردن (مهارت)؛ پیشه کردن (طبیب)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They moved the furniture back to practise their dance routine.","translation":"آنها اثاثیه را به عقب منتقل کردند تا روال رقص خود را تمرین کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568018.mp3"},{"sentence":"It gives students the opportunity to practice their speaking skills.","translation":"این به دانش آموزان این فرصت را می دهد تا مهارت های گفتاری خود را تمرین کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001237.mp3"},{"sentence":"Today we’re going to practise parking.","translation":"امروز می‌خواهیم پارکینگ را تمرین کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317569.mp3"},{"sentence":"She’s practicing for her piano recital.","translation":"او برای رسیتال پیانوی خود تمرین می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317572.mp3"},{"sentence":"Everybody wants to practise their English on me.","translation":"همه می خواهند انگلیسی خود را روی من تمرین کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317575.mp3"},{"sentence":"We practised hitting the ball.","translation":"ضربه زدن به توپ را تمرین کردیم.","audio_url":null}]'::jsonb,6),
('21e1ce4c-aa95-532a-a512-49ac56b21491','fd1821d3-c558-5e28-991c-af5352a2d458',2,null,null,'spoken & written','to use a particular method or custom','[ transitive ]',null,'برای استفاده از یک روش خاص یا سفارشی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This technique is widely practised in Europe (= many people use it ) .","translation":"این تکنیک به طور گسترده در اروپا انجام می شود (= بسیاری از مردم از آن استفاده می کنند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00679.mp3"}]'::jsonb,1),
('096485ad-ebf4-568a-b2fc-ac905e76f228','fd1821d3-c558-5e28-991c-af5352a2d458',3,null,null,'spoken & written','to work as a doctor or lawyer','[ intransitive, transitive ]',null,'برای کار به عنوان پزشک یا وکیل','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"When she has completed her training, she intends to practise in the UK.","translation":"زمانی که او دوره آموزشی خود را به پایان رساند، قصد دارد در انگلستان تمرین کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00680.mp3"},{"sentence":"Gemma is now practising as a dentist.","translation":"جما اکنون به عنوان دندانپزشک مشغول به کار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317591.mp3"}]'::jsonb,2),
