('4b672f1e-b819-5f82-9c8b-69243c1eee57','df87a2a4-e042-5d26-8dcb-3b4d8038dd93',1,null,null,'spoken & written','if a woman or female animal is pregnant, she has an unborn baby growing inside her body',null,null,'باردار، حامله؛ پر از (اندیشه)','{}'::text[],'{}'::text[],array['become pregnant Sally became pregnant, and gave birth to a baby son.','get pregnant informal (= become pregnant ) She got pregnant when she was sixteen.','get somebody pregnant (= make a woman pregnant, usually without planning to ) At least he didn''t get you pregnant.','twelve weeks pregnant/two months pregnant etc The doctor said that she was eight weeks pregnant.','heavily pregnant (= having almost reached the time when you will give birth ) I saw at once that the woman was heavily pregnant.']::text[],'[{"sentence":"medical care for pregnant women","translation":"مراقبت های پزشکی برای زنان باردار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568314.mp3"},{"sentence":"I knew right away that I was pregnant.","translation":"من بلافاصله فهمیدم که باردارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322109.mp3"},{"sentence":"I thought I was too old to get pregnant .","translation":"فکر میکردم سنم زیاده که باردار بشم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322115.mp3"},{"sentence":"She’s about five months pregnant.","translation":"او تقریباً پنج ماهه باردار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322112.mp3"},{"sentence":"Maria was pregnant with her second child.","translation":"ماریا فرزند دومش را باردار بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568320.mp3"},{"sentence":"I didn’t mean to get her pregnant (= make her pregnant ) .","translation":"من قصد نداشتم او را باردار کنم (= باردارش کنم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322119.mp3"},{"sentence":"His wife was heavily pregnant (= almost ready to give birth ) .","translation":"همسرش به شدت حامله بود (= تقریباً آماده زایمان بود).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568327.mp3"}]'::jsonb,7),
