('83546206-f08a-5f4c-b031-ed7ae3b296e0','df075b27-8dfc-5fd8-b1dc-c92585ef68b8',2,'ready to deal with something','آماده برای مقابله با چیزی','spoken & written','ready to do something or deal with a situation','[ not before noun ]',null,'آماده انجام کاری یا مقابله با یک موقعیت است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I wasn’t prepared for all their questions.","translation":"من برای همه سوالات آنها آماده نبودم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000323783.mp3"},{"sentence":"Luckily, we were well prepared for the storm.","translation":"خوشبختانه ما به خوبی برای طوفان آماده شده بودیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568696.mp3"},{"sentence":"The country was ill-prepared to fight another war.","translation":"این کشور برای جنگیدن دیگر آماده نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000323790.mp3"},{"sentence":"There was no news and we were prepared for the worst (= expected something very bad ) .","translation":"هیچ خبری نبود و ما برای بدترین (= انتظار چیز خیلی بدی) آماده شده بودیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000323794.mp3"}]'::jsonb,4),
