('d7dcfba5-06cb-5296-a2a9-e69f882e914a','6786e683-bc0a-54e1-9c5d-0677cb95ecf4',1,null,null,'spoken & written','to save something or someone from being harmed or destroyed',null,null,'حفظ کردن، نگهداری کردن (از نابودی)؛ ماندگار کردن (مزه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We must encourage the planting of new trees and preserve our existing woodlands.","translation":"ما باید کاشت درختان جدید را تشویق کنیم و جنگل های موجود خود را حفظ کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000325702.mp3"}]'::jsonb,1),
('31d85c35-44f8-59bc-890c-eb410e6ab371','6786e683-bc0a-54e1-9c5d-0677cb95ecf4',2,null,null,'spoken & written','to make something continue without changing',null,null,'کاری کنیم که چیزی بدون تغییر ادامه پیدا کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the responsibility of the police to preserve the peace","translation":"مسئولیت پلیس برای حفظ صلح","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560982.mp3"},{"sentence":"Norma tried to preserve a normal family life in difficult circumstances.","translation":"نورما سعی کرد در شرایط سخت زندگی عادی خانوادگی را حفظ کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000325714.mp3"}]'::jsonb,2),
('ff93c837-6d5e-5350-937a-7570e050fde6','6786e683-bc0a-54e1-9c5d-0677cb95ecf4',3,null,null,'spoken & written','to store food for a long time after treating it so that it will not decay',null,null,'بعد از درمان مواد غذایی را برای مدت طولانی نگهداری کنید تا پوسیده نشود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"black olives preserved in brine","translation":"زیتون سیاه نگهداری شده در آب نمک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000325710.mp3"}]'::jsonb,1),
('614e512a-9d1e-5fea-891a-94082a58a325','7740f23f-b7df-520f-9708-ce99eae9bca6',1,null,null,'spoken & written','a substance made from boiling fruit or vegetables with sugar , salt, or vinegar','[ countable usually plural ]',null,'ماده ای که از جوشاندن میوه یا سبزیجات با شکر، نمک یا سرکه به دست می آید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"homemade fruit preserves","translation":"کنسرو میوه های خانگی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560983.mp3"}]'::jsonb,1),
('7cc84cf7-af0c-53c6-8dd7-2aaa4f6035ad','7740f23f-b7df-520f-9708-ce99eae9bca6',2,null,null,'spoken & written','an activity that is only suitable or allowed for a particular group of people','[ singular ]',null,'فعالیتی که فقط برای گروه خاصی از افراد مناسب یا مجاز است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Banking used to be a male preserve .","translation":"بانکداری سابقاً یک حفاظت مردانه بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000326350.mp3"},{"sentence":"The civil service became the preserve of the educated middle class.","translation":"خدمات ملکی در اختیار طبقه متوسط ​​تحصیلکرده قرار گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000326353.mp3"}]'::jsonb,2),
('1e825a7b-b570-57e3-aeeb-69a7bd3c4cae','7740f23f-b7df-520f-9708-ce99eae9bca6',3,null,null,'spoken & written','an area of land or water that is kept for private hunting or fishing','[ countable ]',null,'منطقه ای از زمین یا آبی که برای شکار یا ماهیگیری خصوصی نگهداری می شود','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('dd35eb15-90d3-52c8-a0e1-2c36d58032af','8a50e08d-3f52-5bd5-bfd8-5b6f9bbcc7d0',1,'persuade','متقاعد کردن','spoken & written','an attempt to persuade someone by using influence , arguments , or threats','[ uncountable ]',null,'فشار، نیروی فشار؛ فشار (روانی)؛ فشار (خون)','{}'::text[],'{}'::text[],array['put pressure on somebody We’ve decided to set up a campaign to put pressure on the Government.','exert pressure on somebody formal (= put pressure on them ) They exerted pressure on their colleagues to vote for the change.','bring pressure to bear on somebody (= put pressure on them ) These groups have brought pressure to bear on the government.','put somebody under pressure (= put a lot of pressure on them ) They were put under pressure to sign confessions.','be under pressure Apple growers are under pressure from the public to use fewer chemicals.','come under pressure The new prime minister has already come under pressure from the opposition to call an election.','bow to pressure ( also give in to pressure ) (= do what people want you to do ) He eventually gave in to pressure and resigned.','respond to pressure (= do something as a result of pressure ) The government responded to this pressure and modified the Bill.','strong/intense pressure There was strong pressure for a statement from the president.','considerable pressure Shopkeepers are under considerable pressure to work on Sundays.','increasing/mounting pressure There was increasing pressure on the Chancellor to cut petrol tax.','public/popular pressure (= pressure from the public ) He faces mounting public pressure to resign.','political pressure We did not make this recommendation because of political pressure.','diplomatic pressure (= pressure from other countries'' governments ) The announcement of a ceasefire came after intense diplomatic pressure from the US.']::text[],'[{"sentence":"They are putting pressure on people to vote yes.","translation":"آنها به مردم فشار می آورند که رای مثبت بدهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561078.mp3"},{"sentence":"The minister was under pressure to resign.","translation":"وزیر برای استعفا تحت فشار بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561084.mp3"},{"sentence":"I was under pressure from my parents to become a teacher.","translation":"من تحت فشار پدر و مادرم بودم تا معلم شوم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561088.mp3"},{"sentence":"The Labour government came under pressure from the trade unions.","translation":"دولت کارگر تحت فشار اتحادیه های کارگری قرار گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561089.mp3"},{"sentence":"Pressure for change has become urgent.","translation":"فشار برای تغییر فوری شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000287954.mp3"},{"sentence":"the pressure on all of us to keep slim","translation":"فشار بر همه ما برای لاغر ماندن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561092.mp3"},{"sentence":"He exerts pressure on his kids to get them to do as he wants.","translation":"او بر فرزندانش فشار می آورد تا آنها را وادار کند که هر کاری که می خواهد انجام دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561093.mp3"},{"sentence":"You must never give in to pressure .","translation":"هرگز نباید تسلیم فشار شوید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561103.mp3"}]'::jsonb,8),
('6e323656-55f2-5574-ac58-bbd3a17dd11f','8a50e08d-3f52-5bd5-bfd8-5b6f9bbcc7d0',2,'anxiety/overwork','اضطراب / کار بیش از حد','spoken & written','a way of working or living that causes you a lot of anxiety , especially because you feel you have too many things to do','[ countable, uncountable ]',null,'روشی از کار یا زندگی که باعث اضطراب زیادی در شما می شود، به خصوص به این دلیل که احساس می کنید کارهای زیادی برای انجام دادن دارید.','{}'::text[],'{}'::text[],array['put pressure on somebody We’ve decided to set up a campaign to put pressure on the Government.','exert pressure on somebody formal (= put pressure on them ) They exerted pressure on their colleagues to vote for the change.','bring pressure to bear on somebody (= put pressure on them ) These groups have brought pressure to bear on the government.','put somebody under pressure (= put a lot of pressure on them ) They were put under pressure to sign confessions.','be under pressure Apple growers are under pressure from the public to use fewer chemicals.','come under pressure The new prime minister has already come under pressure from the opposition to call an election.','bow to pressure ( also give in to pressure ) (= do what people want you to do ) He eventually gave in to pressure and resigned.','respond to pressure (= do something as a result of pressure ) The government responded to this pressure and modified the Bill.','strong/intense pressure There was strong pressure for a statement from the president.','considerable pressure Shopkeepers are under considerable pressure to work on Sundays.','increasing/mounting pressure There was increasing pressure on the Chancellor to cut petrol tax.','public/popular pressure (= pressure from the public ) He faces mounting public pressure to resign.','political pressure We did not make this recommendation because of political pressure.','diplomatic pressure (= pressure from other countries'' governments ) The announcement of a ceasefire came after intense diplomatic pressure from the US.']::text[],'[{"sentence":"I feel I’m not able to cope well with the pressures of life.","translation":"احساس می کنم نمی توانم به خوبی با فشارهای زندگی کنار بیایم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561110.mp3"},{"sentence":"The pressure on doctors is increasing steadily.","translation":"فشار بر پزشکان به طور پیوسته در حال افزایش است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000287983.mp3"},{"sentence":"I’m under constant pressure at work.","translation":"من در محل کار دائما تحت فشار هستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561111.mp3"},{"sentence":"The pressures of work can make you ill.","translation":"فشار کار می تواند شما را بیمار کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561117.mp3"},{"sentence":"a high pressure job","translation":"یک کار با فشار بالا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561121.mp3"},{"sentence":"athletes who show grace under pressure (= who behave well when they are anxious )","translation":"ورزشکارانی که تحت فشار ظرافت نشان می دهند (= که در مضطرب خوب رفتار می کنند)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843062.mp3"}]'::jsonb,6),
('95bbb1fc-53ba-5090-94ac-70dd9f3101fc','8a50e08d-3f52-5bd5-bfd8-5b6f9bbcc7d0',3,'causing change','باعث تغییر می شود','spoken & written','events or conditions that cause changes and affect the way a situation develops , especially in economics or politics','[ countable, uncountable ]',null,'رویدادها یا شرایطی که باعث تغییر می شوند و بر نحوه توسعه یک موقعیت تأثیر می گذارند، به ویژه در اقتصاد یا سیاست','{}'::text[],'{}'::text[],array['put pressure on somebody We’ve decided to set up a campaign to put pressure on the Government.','exert pressure on somebody formal (= put pressure on them ) They exerted pressure on their colleagues to vote for the change.','bring pressure to bear on somebody (= put pressure on them ) These groups have brought pressure to bear on the government.','put somebody under pressure (= put a lot of pressure on them ) They were put under pressure to sign confessions.','be under pressure Apple growers are under pressure from the public to use fewer chemicals.','come under pressure The new prime minister has already come under pressure from the opposition to call an election.','bow to pressure ( also give in to pressure ) (= do what people want you to do ) He eventually gave in to pressure and resigned.','respond to pressure (= do something as a result of pressure ) The government responded to this pressure and modified the Bill.','strong/intense pressure There was strong pressure for a statement from the president.','considerable pressure Shopkeepers are under considerable pressure to work on Sundays.','increasing/mounting pressure There was increasing pressure on the Chancellor to cut petrol tax.','public/popular pressure (= pressure from the public ) He faces mounting public pressure to resign.','political pressure We did not make this recommendation because of political pressure.','diplomatic pressure (= pressure from other countries'' governments ) The announcement of a ceasefire came after intense diplomatic pressure from the US.']::text[],'[{"sentence":"inflationary pressures","translation":"فشارهای تورمی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561129.mp3"},{"sentence":"Analysts expect the pound to come under pressure .","translation":"تحلیلگران انتظار دارند که پوند تحت فشار قرار گیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561130.mp3"},{"sentence":"Slowing the arms race relieved pressure on the Soviet economic system.","translation":"کند کردن مسابقه تسلیحاتی فشار بر سیستم اقتصادی شوروی را کاهش داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843068.mp3"},{"sentence":"The 1990s brought increased economic pressure to bear on all business activities.","translation":"دهه 1990 فشار اقتصادی فزاینده‌ای را بر تمام فعالیت‌های تجاری وارد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843069.mp3"}]'::jsonb,4),
