('dbf2e93a-c5ac-5991-a3de-a06d0915bd91','1f8eba11-204b-5faa-a955-894e03ef8e26',1,'on a list','در یک لیست','spoken & written','to put someone’s or something’s name on an official list','[ intransitive, transitive ]',null,'ثبت نام کردن؛ ثبت کردن (سند)؛ ثبت (نامه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The tanker is registered in Rotterdam.","translation":"این نفتکش در روتردام ثبت شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000769970.mp3"},{"sentence":"How many students have registered for English classes?","translation":"چند دانش آموز در کلاس های زبان انگلیسی ثبت نام کرده اند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001661935.mp3"},{"sentence":"You must bring your insurance card with you when you register with a dentist or doctor.","translation":"هنگام ثبت نام نزد دندانپزشک یا پزشک باید کارت بیمه خود را همراه داشته باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001661938.mp3"},{"sentence":"The baby’s birth was registered this morning.","translation":"تولد نوزاد صبح امروز ثبت شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001661941.mp3"}]'::jsonb,4),
('9db5388a-15d0-5187-b67c-2bbb22995a73','1f8eba11-204b-5faa-a955-894e03ef8e26',2,'state your opinion','نظر خود را بیان کنید','formal','to officially state your opinion about something so that everyone knows what you think or feel','[ transitive ]',null,'به طور رسمی نظر خود را در مورد چیزی اعلام کنید تا همه بدانند که چه فکر یا احساسی دارید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The delegation registered a formal protest with US embassy officials Wednesday.","translation":"این هیئت روز چهارشنبه اعتراض رسمی خود را با مقامات سفارت ایالات متحده ثبت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001661942.mp3"}]'::jsonb,1),
('5eb52d18-4f9f-57f1-bf30-a5568f2e8b4d','1f8eba11-204b-5faa-a955-894e03ef8e26',3,'realize','متوجه شدن','spoken & written','if something registers, or if you register it, you realize or notice it, and then remember it','[ intransitive usually in negatives, transitive ]',null,'اگر چیزی ثبت شود، یا اگر آن را ثبت کنید، متوجه می شوید یا متوجه آن می شوید و سپس آن را به خاطر می آورید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She had told me her name before, but I guess it didn’t register.","translation":"قبلاً اسمش را به من گفته بود، اما حدس می‌زنم که ثبت نشده باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000769999.mp3"},{"sentence":"I’d been standing there for several minutes before he registered my presence.","translation":"قبل از اینکه او حضور من را ثبت کند، چند دقیقه آنجا ایستاده بودم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000770000.mp3"}]'::jsonb,2),
('45edfa1d-9ceb-5a39-8829-39b9ee9f6068','1f8eba11-204b-5faa-a955-894e03ef8e26',4,'measurement','اندازه گیری','spoken & written','if an instrument registers an amount or if something registers on it, the instrument shows that amount','[ intransitive, transitive ]',null,'اگر ابزاری مقداری را ثبت کند یا چیزی روی آن ثبت شود، ابزار آن مقدار را نشان می دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The thermometer registered 98.6°.","translation":"دماسنج 98.6 درجه را ثبت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000770006.mp3"},{"sentence":"The earthquake registered 7.2 on the Richter scale.","translation":"شدت این زمین لرزه 7.2 در مقیاس ریشتر بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001661948.mp3"}]'::jsonb,2),
('fb8537dd-2bbd-5a66-9307-8453f50b2c17','1f8eba11-204b-5faa-a955-894e03ef8e26',5,'show a feeling','یک احساس را نشان دهد','formal','to show or express a feeling','[ transitive ]',null,'برای نشان دادن یا بیان یک احساس','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Her face registered shock and anger.","translation":"چهره او شوک و عصبانیت را ثبت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000769986.mp3"}]'::jsonb,1),
