('1c348f29-6d7e-52b2-95bf-840301a3fdab','bf800ae2-96a9-51de-a764-5f30c57e29bc',4,'educational','آموزشی','spoken & written','something such as a book, film , or picture used by teachers or students to provide information','[ countable ]',null,'چیزی مانند کتاب، فیلم یا تصویری که معلمان یا دانش آموزان برای ارائه اطلاعات استفاده می کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"resources for learning","translation":"منابع برای یادگیری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745516.mp3"},{"sentence":"a valuable new computer resource","translation":"یک منبع جدید کامپیوتری با ارزش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745517.mp3"}]'::jsonb,2),
('a92f0d6a-33f5-5525-a73e-f226362578ac','bf800ae2-96a9-51de-a764-5f30c57e29bc',5,'practical ability','توانایی عملی','formal','the ability to deal with practical problems','[ uncountable ]',null,'توانایی مقابله با مشکلات عملی',array['resourcefulness']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a man of great resource","translation":"مردی با منابع بزرگ","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745528.mp3"}]'::jsonb,1),
('f7719d71-c20b-5101-9e1c-49d8c214a527','130f186a-9d0f-5737-9f51-97503751b281',1,null,null,'spoken & written','to provide money or other resources for something',null,null,'تهیه پول یا منابع دیگر برای چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The program wasn’t adequately resourced.","translation":"برنامه به اندازه کافی منابع نداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745541.mp3"}]'::jsonb,1),
('a4365be2-4974-5361-a12b-5713403e8dc0','e1313808-e6ec-555a-8632-b5b974a8b4cc',1,null,null,'spoken & written','something that is done as a reaction to something that has happened or been said','[ countable, uncountable ]',null,'پاسخ، واکنش؛ پاسخ (درخواست)؛ پاسخ (حس)','{}'::text[],'{}'::text[],array['a positive/favourable response The product met with a highly positive response from the public.','a negative response In Russia, the planned expansion provoked a negative response.','an enthusiastic response There has been an enthusiastic response to the introduction of soccer coaching for girls.','an angry response His comments sparked an angry response from opposition politicians.','a good/encouraging response (= when people like something or show interest ) We’ve had a good response from the public.','somebody’s immediate response When he was sentenced, his immediate response was to appeal.','a direct response Her resignation was in direct response to the party’s poor results in the local elections.','an appropriate response She laughed, which didn''t really seem an appropriate response.','a strong response The photograph provoked a strong response from many people.','an emotional response When she died, the emotional response was extraordinary.','get a positive etc response She got an enthusiastic response to her suggestion.','receive a positive etc response (= get it ) The proposal has received a positive response from most left-wing voters.','meet with a positive etc response (= get it ) The change met with a mixed response from employees.','provoke a response The report provoked a strong response from a number of senior politicians.','draw/bring a response from somebody The appeal for aid brought a big response from the West.']::text[],'[{"sentence":"the public’s response to our appeal for help","translation":"پاسخ مردم به درخواست کمک ما","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562977.mp3"},{"sentence":"The law was passed in response to public pressure.","translation":"این قانون در پاسخ به فشار عمومی به تصویب رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001769094.mp3"},{"sentence":"The exhibition has received a positive response from visitors.","translation":"این نمایشگاه با استقبال مثبت بازدیدکنندگان مواجه شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001876903.mp3"},{"sentence":"The decision provoked an angry response from residents.","translation":"این تصمیم واکنش خشمگینانه ساکنان را برانگیخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745940.mp3"},{"sentence":"His immediate response was one of disbelief.","translation":"پاسخ فوری او یک ناباوری بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562987.mp3"},{"sentence":"Emmett’s new exhibition has met with a favourable response from critics.","translation":"نمایشگاه جدید امت با واکنش مثبت منتقدان روبرو شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562991.mp3"}]'::jsonb,6),
('8f321f11-689f-5f8d-b489-c567f9d7d321','e1313808-e6ec-555a-8632-b5b974a8b4cc',2,null,null,'spoken & written','something that is said or written as a reply','[ countable ]',null,'چیزی که به عنوان پاسخ گفته یا نوشته می شود','{}'::text[],'{}'::text[],array['a positive/favourable response The product met with a highly positive response from the public.','a negative response In Russia, the planned expansion provoked a negative response.','an enthusiastic response There has been an enthusiastic response to the introduction of soccer coaching for girls.','an angry response His comments sparked an angry response from opposition politicians.','a good/encouraging response (= when people like something or show interest ) We’ve had a good response from the public.','somebody’s immediate response When he was sentenced, his immediate response was to appeal.','a direct response Her resignation was in direct response to the party’s poor results in the local elections.','an appropriate response She laughed, which didn''t really seem an appropriate response.','a strong response The photograph provoked a strong response from many people.','an emotional response When she died, the emotional response was extraordinary.','get a positive etc response She got an enthusiastic response to her suggestion.','receive a positive etc response (= get it ) The proposal has received a positive response from most left-wing voters.','meet with a positive etc response (= get it ) The change met with a mixed response from employees.','provoke a response The report provoked a strong response from a number of senior politicians.','draw/bring a response from somebody The appeal for aid brought a big response from the West.']::text[],'[{"sentence":"‘Sure, why not?’ was his response to all of Billie’s suggestions.","translation":"«مطمئنا، چرا که نه؟» پاسخ او به همه پیشنهادات بیلی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001769095.mp3"},{"sentence":"Carl made no response , and carried on with his meal.","translation":"کارل هیچ پاسخی نداد و به غذایش ادامه داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001769096.mp3"},{"sentence":"I am writing in response to your letter of June 12.","translation":"من در پاسخ به نامه 12 ژوئن شما می نویسم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001769104.mp3"},{"sentence":"Ronni merely groaned in response.","translation":"رونی در پاسخ فقط ناله کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001563012.mp3"}]'::jsonb,4),
('88fe8c78-8970-5a61-b4a7-d3f3de038439','b7bf639a-61b3-592a-a3cb-b5e192283fc8',1,null,null,'spoken & written','to limit or control the size , amount, or range of something',null,null,'محدود کردن، محدودسازی کردن (دسترسی)؛ مهار کردن (مقدار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The new law restricts the sale of hand guns.","translation":"قانون جدید فروش اسلحه دستی را محدود می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746748.mp3"},{"sentence":"You may need to restrict access to certain files (= limit the number of people who can read them ) .","translation":"ممکن است لازم باشد دسترسی به فایل های خاصی را محدود کنید (= تعداد افرادی که می توانند آنها را بخوانند محدود کنید).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001563238.mp3"},{"sentence":"The agreement will restrict competition.","translation":"این توافق رقابت را محدود خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001563243.mp3"},{"sentence":"In future we will restrict class sizes to 20 students.","translation":"در آینده تعداد کلاس ها را به 20 دانش آموز محدود خواهیم کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746751.mp3"}]'::jsonb,4),
('5284ed8f-7bed-5764-9424-01340ff27aa7','b7bf639a-61b3-592a-a3cb-b5e192283fc8',2,null,null,'spoken & written','to limit someone’s actions or movements',null,null,'محدود کردن اعمال یا حرکات کسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The cramped living conditions severely restricted the children’s freedom to play.","translation":"شرایط تنگ زندگی به شدت آزادی کودکان را برای بازی محدود می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746759.mp3"}]'::jsonb,1),
('e1aa176d-0eda-51ad-b27d-53eaa4d2d3da','b7bf639a-61b3-592a-a3cb-b5e192283fc8',3,null,null,'spoken & written',null,null,'restrict yourself/somebody to (doing) something','محدود کردن، محدودسازی کردن (دسترسی)؛ مهار کردن (مقدار)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
