('0a70aa17-6e00-5a55-8d7d-11836b098fc4','a9652084-8fdc-54a2-ac04-0588d37adfbb',2,null,null,'spoken & written','a cake consisting of two layers with jam and cream between them','[ countable ]',null,'یک کیک از دو لایه با مربا و خامه بین آنها','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a raspberry sponge sandwich","translation":"یک ساندویچ اسفنجی تمشک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633944.mp3"}]'::jsonb,1),
('b547af9a-4f88-564f-8648-65e8ff1991dc','192a0826-df26-50ce-b51f-ed4540dad07e',1,null,null,'spoken & written','to put something in a very small space between two other things',null,null,'قرار دادن چیزی در یک فضای بسیار کوچک بین دو چیز دیگر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A layer of transparent material is sandwiched between the pieces of glass.","translation":"لایه ای از مواد شفاف بین تکه های شیشه قرار گرفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000742882.mp3"}]'::jsonb,1),
('514f8514-cb6a-5237-a023-39204f0153f1','a348e273-dabd-5c0d-b7cd-e6ab48c5b2e6',1,null,null,'spoken & written','a plan of what someone is going to do and when they are going to do it',null,null,'برنامه زمانی، جدول ساعاتی؛ برنامگی (ساعت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The majority of holiday flights depart and arrive on schedule.","translation":"اکثر پروازهای تعطیلات طبق برنامه حرکت می کنند و می رسند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001581737.mp3"},{"sentence":"Meg’s new book is still well ahead of schedule.","translation":"کتاب جدید مگ هنوز خیلی جلوتر از برنامه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000718799.mp3"},{"sentence":"How can he fit everything into his busy schedule ?","translation":"او چگونه می تواند همه چیز را در برنامه شلوغ خود جای دهد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001581738.mp3"},{"sentence":"I’m going to be working to a very tight schedule (= including a lot of things that must be done in a short time ) .","translation":"من قرار است با یک برنامه بسیار فشرده کار کنم (= شامل کارهای زیادی که باید در مدت زمان کوتاهی انجام شوند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001581742.mp3"}]'::jsonb,4),
('e8ae0f53-365d-5f7f-a8c5-fb1292f32ef0','a348e273-dabd-5c0d-b7cd-e6ab48c5b2e6',2,null,null,'spoken & written','a list that shows the times that buses , trains etc leave or arrive at a particular place',null,null,'فهرستی که زمان هایی را نشان می دهد که اتوبوس ها، قطارها و غیره از یک مکان خاص خارج می شوند یا به آن می رسند','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('bd6a7514-adaa-5885-83f3-e46904714b08','a348e273-dabd-5c0d-b7cd-e6ab48c5b2e6',3,null,null,'spoken & written','a formal list of something, for example prices',null,null,'یک لیست رسمی از چیزی، به عنوان مثال قیمت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a schedule of postal charges","translation":"جدول هزینه های پستی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000718813.mp3"}]'::jsonb,1),
('3f54108e-acfe-53bd-a718-58d683c2a840','63b0bdc9-6c6d-5485-9a8b-397c2bc329a3',1,null,null,'spoken & written','to plan that something will happen at a particular time',null,null,'زمان‌بندی کردن؛ در برنامه گذاشتن؛ موعد گذاشتن (برای)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The elections are scheduled for mid-June.","translation":"قرار است انتخابات اواسط ژوئن برگزار شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000718825.mp3"},{"sentence":"Her first album is scheduled for release in September.","translation":"اولین آلبوم او برای انتشار در سپتامبر برنامه ریزی شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001581751.mp3"},{"sentence":"Meetings are scheduled to take place all over the country.","translation":"قرار است جلساتی در سراسر کشور برگزار شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000718828.mp3"},{"sentence":"Prices include scheduled flights from Heathrow.","translation":"قیمت ها شامل پروازهای برنامه ریزی شده از هیترو است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001581757.mp3"},{"sentence":"We will not cancel your holiday less than eight weeks before the scheduled departure date .","translation":"ما تعطیلات شما را کمتر از هشت هفته قبل از تاریخ برنامه ریزی شده لغو نمی کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040196.mp3"}]'::jsonb,5),
('4b8eec67-abb2-55b6-b2ca-9998e1a0ad10','d0c93ade-68ec-5333-afe9-0248fef6aebd',1,null,null,'spoken & written','used when you want to give a second point or fact , or give a second reason for something',null,null,'دوم، ثانیاً؛ بعلاوه (دلیل دوم)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Firstly, they are not efficient, and secondly, they are expensive to make.","translation":"اولاً آنها کارآمد نیستند و ثانیاً ساخت آنها گران است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582424.mp3"}]'::jsonb,1),
('5337e06a-b6e7-5269-b5ac-2f0892c823c4','5f6a6a84-b99d-5283-a3df-b8c23a154a90',1,'protection from danger','محافظت در برابر خطر','spoken & written','things that are done to keep a person, building, or country safe from danger or crime','[ uncountable ]',null,'امنیت، ایمنی؛ امنیت (کشور)؛ امنیت (درب)','{}'::text[],'{}'::text[],array['tight/strict (= good security, so that something is very safe ) The event passed off peacefully, amid tight security.','lax (= not good enough, so that something is not as safe as it should be ) The prime minister denied that border security had been lax.','heightened security (= more than usual ) There is heightened security around Heathrow following the bomb threats.','national/state security (= security of a country ) Did the article contain any information that is damaging to national security?','personal security (= security of an individual person ) The department is responsible for the president’s personal security.','improve/tighten security (= make it better ) Mexico has tightened security along its southern border.','the security services/forces (= the police, army etc ) Clashes with the security forces continued.','security measures/arrangements Residents have been warned to take extra security measures following a spate of burglaries.','a security check There are security checks at the entrance to the courtrooms.','a security guard There are armed security guards outside the palace.','security staff Teams of security staff guard the laboratory.','a security camera A car park security camera captured the attack.','a security system (= a system of cameras, alarms etc to provide security ) The first stage would be to install security systems and adequate lighting in churches.','a security risk His presence in the area posed a significant security risk.','for security reasons He can’t be identified for security reasons.','a breach of security (= when something happens that the security should have stopped ) There was a serious breach of security at the prison last Friday.']::text[],'[{"sentence":"The trial was held under tight security .","translation":"دادگاه تحت تدابیر شدید امنیتی برگزار شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919306.mp3"},{"sentence":"lax security at airline check-in desks","translation":"امنیت ضعیف در میزهای پذیرش هواپیمایی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919310.mp3"},{"sentence":"terrorist activity that is a threat to national security","translation":"فعالیت تروریستی که تهدیدی برای امنیت ملی است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919313.mp3"},{"sentence":"The prison was ordered to tighten security after a prisoner escaped yesterday.","translation":"پس از فرار یک زندانی دیروز، دستور تشدید تدابیر امنیتی به این زندان صادر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919316.mp3"},{"sentence":"The Security Commission investigates breaches of security .","translation":"کمیسیون امنیت نقض های امنیتی را بررسی می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919324.mp3"},{"sentence":"We have been asked not to say anything for security reasons .","translation":"از ما خواسته شده که به دلایل امنیتی چیزی نگوییم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919328.mp3"},{"sentence":"The security forces opened fire, killing two people.","translation":"نیروهای امنیتی تیراندازی کردند و دو نفر را کشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919332.mp3"},{"sentence":"The thief was caught on a security camera .","translation":"دزد توسط دوربین امنیتی دستگیر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919336.mp3"},{"sentence":"There are strict security checks on everyone entering the Opera House.","translation":"کنترل‌های امنیتی شدیدی برای همه افرادی که وارد خانه اپرا می‌شوند وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919340.mp3"},{"sentence":"A large number of homes lack adequate security measures .","translation":"تعداد زیادی از خانه ها فاقد تدابیر امنیتی کافی هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919344.mp3"}]'::jsonb,10),
