('90062d37-e74a-595b-9d7c-cb0475dfd202','14e2e519-283a-5840-8a1a-734da7c6fd89',1,null,null,'spoken & written','reasonable , practical , and showing good judgment',null,null,'معقول، خردمند؛ بجاست (پاسخ)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She seems very sensible.","translation":"او بسیار معقول به نظر می رسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000700882.mp3"},{"sentence":"sensible advice","translation":"توصیه معقول","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000700881.mp3"},{"sentence":"It’s sensible to keep a note of your passport number.","translation":"عاقلانه است که شماره پاسپورت خود را یادداشت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777412.mp3"},{"sentence":"Moving house seemed like the sensible thing to do .","translation":"خانه تکانی به نظر کار معقولی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000700880.mp3"}]'::jsonb,4),
('6f15386d-0ebb-5635-b4da-d7d4b69078b2','14e2e519-283a-5840-8a1a-734da7c6fd89',2,null,null,'spoken & written','suitable for a particular purpose , and practical rather than fashionable',null,null,'مناسب برای یک هدف خاص، و عملی به جای مد روز','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Eat a sensible diet and exercise daily.","translation":"رژیم غذایی معقول داشته باشید و روزانه ورزش کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001635290.mp3"},{"sentence":"an old woman in sensible shoes and a neat skirt","translation":"پیرزنی با کفش های معقول و دامن مرتب","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001635291.mp3"}]'::jsonb,2),
('67225a8d-664c-53b8-a08b-91f65dd5a7f3','14e2e519-283a-5840-8a1a-734da7c6fd89',3,null,null,'formal','noticeable',null,null,'قابل توجه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a sensible increase in temperature","translation":"افزایش معقول دما","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000700899.mp3"}]'::jsonb,1),
('ce71a664-8b6e-5839-b28f-8c062e421478','14e2e519-283a-5840-8a1a-734da7c6fd89',4,null,null,'spoken & written',null,null,'be sensible of something','معقول، خردمند؛ بجاست (پاسخ)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('a79c89c6-bdfa-52e5-b253-8a223b26cb55','07728361-fa19-5578-a4f3-a60eb244cdbf',1,null,null,'spoken & written','a group of words that usually contains a subject and a verb , and expresses a complete idea. Sentences written in English begin with a capital letter and usually end with a full stop or a question mark',null,null,'جمله، بخش (گفتار)؛ حکم (دادگاه)؛ جمله (رابطه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"His voice dropped at the end of the sentence.","translation":"صدایش در پایان جمله کم شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001982852.mp3"},{"sentence":"It’s difficult to sum it up in one sentence.","translation":"خلاصه کردن آن در یک جمله دشوار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001982855.mp3"},{"sentence":"In a few short sentences, Quinn explained what he had done.","translation":"کوین در چند جمله کوتاه توضیح داد که چه کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001982858.mp3"}]'::jsonb,3),
('072d47d9-115f-5952-ae04-583ecdcff650','07728361-fa19-5578-a4f3-a60eb244cdbf',2,null,null,'spoken & written','a punishment that a judge gives to someone who is guilty of a crime',null,null,'مجازاتی که قاضی برای کسی که مرتکب جرم شده است می دهد','{}'::text[],'{}'::text[],array['get/receive a sentence ( also be given a sentence ) She was given a three-year prison sentence.','face a sentence (= be likely to receive a sentence ) He faces a long prison sentence if he is caught.','serve a sentence (= spend time in prison ) Her husband is serving a two-year sentence for credit-card fraud.','a crime carries a sentence (= that is the punishment for that crime ) Rape should carry an automatic life sentence.','impose/hand down a sentence (= officially give someone a sentence ) The judge imposed a three-year sentence.','pass sentence formal (= officially say what someone’s punishment will be ) It is now my duty to pass sentence.','a stiff/long sentence (= a long time in prison ) Police officers are demanding stiffer sentences for offenders.','a light/short sentence (= a short time in prison ) We’re hoping that he gets off with a light sentence.','a prison/jail sentence ( also a custodial sentence British English formal ) If found guilty, he faces a long jail sentence.','a non-custodial sentence British English formal (= a punishment in which a person does not go to prison ) The judge said the offence was too serious for a non-custodial sentence.','a five-year/eight-year etc sentence (= five/eight etc years in prison ) He was serving an eight-year sentence for burglary.','the maximum sentence (= the most that can be given for a particular crime ) The maximum sentence for this offence is five years.','a life sentence (= prison for the rest of your life, or a very long time ) In 1978 he was given a life sentence for attacking a 72-year-old woman.','a death sentence (= a punishment of death ) Death sentences were handed down to eight of the accused.','a suspended sentence (= one which someone will serve only if they commit another crime ) Her attacker got a two-year suspended sentence.']::text[],'[{"sentence":"She received an eight-year prison sentence.","translation":"او به هشت سال زندان محکوم شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919383.mp3"},{"sentence":"He has just begun a life sentence for murder.","translation":"او به تازگی حکم حبس ابد را برای قتل آغاز کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001919401.mp3"}]'::jsonb,2),
('fb49a9e7-c703-59f9-b4ed-1b99ada45cf9','a9995977-297d-56ab-a49f-b61871399dea',1,null,null,'spoken & written','if a judge sentences someone who is guilty of a crime, they give them a punishment',null,null,'اگر قاضی کسی را که مرتکب جرمی شده محکوم کند، او را مجازات می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Sanchez was sentenced to three years in prison.","translation":"سانچز به سه سال زندان محکوم شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701181.mp3"}]'::jsonb,1),
('434e995b-4724-59c9-93d3-050808f866cb','7ec45d77-9ecd-5c6f-a411-6fd906fe9d41',1,null,null,'spoken & written','different',null,null,'جدا، مجزا؛ جدا (مسیر)؛ مجزا (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Use separate knives for raw and cooked meat.","translation":"برای گوشت خام و پخته از چاقوهای جداگانه استفاده کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701392.mp3"},{"sentence":"My wife and I have separate bank accounts.","translation":"من و همسرم حساب های بانکی جداگانه داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777451.mp3"}]'::jsonb,2),
('95b535bd-489b-506e-8df1-284c7ad3c3a8','7ec45d77-9ecd-5c6f-a411-6fd906fe9d41',2,null,null,'spoken & written','not related to or not affected by something else',null,null,'به چیز دیگری مرتبط نیست یا تحت تأثیر چیز دیگری نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"That’s a separate issue.","translation":"این یک موضوع جداگانه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777452.mp3"},{"sentence":"He was attacked on two separate occasions.","translation":"او در دو نوبت جداگانه مورد حمله قرار گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777453.mp3"},{"sentence":"He tries to keep his professional life completely separate from his private life.","translation":"او سعی می کند زندگی حرفه ای خود را کاملا جدا از زندگی خصوصی خود نگه دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701402.mp3"}]'::jsonb,3),
('3961d43f-abdb-54cd-b0fd-ddf76b23c004','7ec45d77-9ecd-5c6f-a411-6fd906fe9d41',3,null,null,'spoken & written','not joined to or touching something else',null,null,'به چیز دیگری نپیوسته یا لمس نمی کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The gym and the sauna are in separate buildings.","translation":"سالن بدنسازی و سونا در ساختمان های جداگانه قرار دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001635387.mp3"},{"sentence":"Keep the fish separate from the other food.","translation":"ماهی را جدا از غذای دیگر نگه دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701395.mp3"}]'::jsonb,2),
('029276b2-1dbd-5110-929d-737b04104bfc','7ec45d77-9ecd-5c6f-a411-6fd906fe9d41',4,null,null,'spoken & written',null,null,'go your separate ways','جدا، مجزا؛ جدا (مسیر)؛ مجزا (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('37318481-c0a2-5262-bc09-d90b8071f506','640a41ba-5468-5f3c-9c7e-f45f00ddb0f9',1,'be between','بین باشد','spoken & written','if something separates two places or two things, it is between them so that they are not touching each other','[ transitive ]',null,'جدا کردن؛ تفکیک کردن (دست)؛ متمایز کردن (از)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The lighthouse is separated from the land by a wide channel.","translation":"فانوس دریایی با کانالی وسیع از زمین جدا شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701435.mp3"}]'::jsonb,1),
('da9e9580-2431-56dc-aa1c-8dcd247fa92b','640a41ba-5468-5f3c-9c7e-f45f00ddb0f9',2,'divide','تقسیم کنید','spoken & written','to divide or split into different parts, or to make something do this','[ intransitive, transitive ]',null,'تقسیم کردن یا تقسیم کردن به قسمت های مختلف، یا کاری برای انجام این کار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This will keep your dressing from separating.","translation":"این کار از جدا شدن پانسمان شما جلوگیری می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701442.mp3"},{"sentence":"At this point, the satellite separates from its launcher.","translation":"در این مرحله ماهواره از پرتابگر خود جدا می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701445.mp3"},{"sentence":"Separate the students into four groups.","translation":"دانش آموزان را به چهار گروه تقسیم کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701448.mp3"},{"sentence":"First, separate the eggs (= divide the white part from the yellow part ) .","translation":"ابتدا تخم مرغ ها را جدا کنید (= قسمت سفید را از قسمت زرد تقسیم کنید).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001635396.mp3"}]'::jsonb,4),
('f9cd6bf8-6686-5593-b5a1-7dd1c6a3ab78','640a41ba-5468-5f3c-9c7e-f45f00ddb0f9',3,'stop living together','زندگی مشترک را متوقف کنید','spoken & written','if two people who are married or have been living together separate, they start to live apart','[ intransitive ]',null,'اگر دو نفر که ازدواج کرده اند یا با هم زندگی می کنند جدا از هم زندگی می کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Jill and John separated a year ago.","translation":"جیل و جان یک سال پیش از هم جدا شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701458.mp3"},{"sentence":"I decided to separate from my partner.","translation":"تصمیم گرفتم از شریکم جدا شوم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00777.mp3"},{"sentence":"She and her husband separated.","translation":"او و شوهرش از هم جدا شدند.","audio_url":null},{"sentence":"She separated from her husband.","translation":"از شوهرش جدا شد.","audio_url":null},{"sentence":"She and her husband separated from each other.","translation":"او و شوهرش از یکدیگر جدا شدند.","audio_url":null}]'::jsonb,5),
('a310de3f-52df-5f11-8ae8-5e349da03f5f','640a41ba-5468-5f3c-9c7e-f45f00ddb0f9',4,'recognize difference','تشخیص تفاوت','spoken & written','to recognize that one thing or idea is different from another','[ transitive ]',null,'تشخیص اینکه یک چیز یا ایده با چیز دیگر متفاوت است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She finds it difficult to separate fact from fantasy.","translation":"جدا کردن واقعیت از خیال برای او دشوار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701466.mp3"}]'::jsonb,1),
('e353674c-34a1-58b4-aeba-4c7589e41d47','640a41ba-5468-5f3c-9c7e-f45f00ddb0f9',5,'move apart','از هم جدا شوند','spoken & written','if people separate, or if someone or something separates them, they move apart','[ intransitive, transitive ]',null,'اگر مردم از هم جدا شوند، یا اگر کسی یا چیزی آنها را از هم جدا کند، از هم دور می شوند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Ed stepped in to separate the two dogs.","translation":"اد وارد عمل شد تا دو سگ را از هم جدا کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001635401.mp3"},{"sentence":"In the fog, they got separated from the group.","translation":"در مه از گروه جدا شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701474.mp3"}]'::jsonb,2),
('c92d7532-cc14-51e5-b584-75ecc175ba14','640a41ba-5468-5f3c-9c7e-f45f00ddb0f9',6,'make somebody/something different','کسی/چیزی متفاوت ساختن','spoken & written','to be the quality or fact that makes someone or something different from other people or things','[ transitive ]',null,'کیفیت یا واقعیتی باشد که کسی یا چیزی را از افراد یا چیزهای دیگر متفاوت می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The capacity to think separates humans from animals.","translation":"ظرفیت تفکر انسان را از حیوانات جدا می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001635404.mp3"}]'::jsonb,1),
('4f24488f-59ff-55b1-a475-e9097981805a','640a41ba-5468-5f3c-9c7e-f45f00ddb0f9',7,'better/older','بهتر/پیرتر','spoken & written','if an amount separates two things, one thing is better or older than the other by that amount','[ transitive ]',null,'اگر مقداری دو چیز را از هم جدا کند، یک چیز در آن مقدار از دیگری بهتر یا قدیمی تر است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Three points now separate the two teams.","translation":"حالا سه امتیاز دو تیم را از هم جدا می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777462.mp3"}]'::jsonb,1),
