('c4e6edb6-694b-5764-911b-38a61044bb81','052c0ff1-2899-528a-8e4e-dc45890580a6',1,null,null,'spoken & written','the order that something happens or exists in, or the order it is supposed to happen or exist in','[ countable, uncountable ]',null,'توالی، ترتیب (رخداد)؛ توالی (رنگ)؛ توالی (ورزش)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The questions should be asked in a logical sequence .","translation":"سوالات باید در یک توالی منطقی پرسیده شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777474.mp3"},{"sentence":"Be careful to perform the actions in the correct sequence .","translation":"مراقب باشید که اقدامات را به ترتیب صحیح انجام دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777478.mp3"},{"sentence":"Number them in sequence, 1,2, 3 etc.","translation":"آنها را به ترتیب، 1،2، 3 و غیره شماره گذاری کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777484.mp3"},{"sentence":"The chapters may be studied out of sequence.","translation":"ممکن است فصل ها بدون ترتیب مطالعه شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777487.mp3"}]'::jsonb,4),
('6e3a54f6-1064-504a-b86a-b1e78a14d5e4','052c0ff1-2899-528a-8e4e-dc45890580a6',2,null,null,'spoken & written','a series of related events , actions etc that happen or are done in a particular order','[ countable ]',null,'مجموعه ای از رویدادها، اقدامات و غیره مرتبط که به ترتیب خاصی اتفاق می افتد یا انجام می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He’s had a sequence of business failures.","translation":"او یک سری شکست های تجاری داشته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777490.mp3"},{"sentence":"the sequence of events leading up to the war","translation":"توالی وقایع منتهی به جنگ","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701733.mp3"}]'::jsonb,2),
('47b4dbaf-801d-50b8-8804-7da15bcfae9a','052c0ff1-2899-528a-8e4e-dc45890580a6',3,null,null,'spoken & written','one part of a story , film etc that deals with a single subject or action','[ countable ]',null,'بخشی از یک داستان، فیلم و غیره که به یک موضوع یا عمل می پردازد',array['scene']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the dream sequence in the film","translation":"سکانس رویا در فیلم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000701747.mp3"}]'::jsonb,1),
('01e9660f-b92f-5e9d-be85-07b01918d7e1','0a1a6a52-5100-5f39-92ac-174d1640884a',1,null,null,'spoken & written','very surprising , upsetting , and difficult to believe',null,null,'فجیع، تکان‌دهنده؛ ناخوشایند (خبر)؛ بد (رفتار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the shocking news that Mark had hanged himself","translation":"خبر تکان دهنده ای که مارک خود را حلق آویز کرده است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001589006.mp3"},{"sentence":"a shocking discovery","translation":"یک کشف تکان دهنده","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001589007.mp3"},{"sentence":"The anger in his face was shocking.","translation":"عصبانیت در چهره اش تکان دهنده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001589008.mp3"}]'::jsonb,3),
('d97140b4-2997-5dff-98d3-ad36059edf38','0a1a6a52-5100-5f39-92ac-174d1640884a',2,null,null,'spoken & written','morally wrong',null,null,'از نظر اخلاقی اشتباه است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s shocking that hospitals can deny help to older people.","translation":"این تکان دهنده است که بیمارستان ها می توانند کمک به افراد مسن را رد کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001589009.mp3"},{"sentence":"a shocking waste of money","translation":"هدر دادن پول تکان دهنده","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001589012.mp3"}]'::jsonb,2),
('fc98861e-8b61-55af-9474-9cad064f545c','0a1a6a52-5100-5f39-92ac-174d1640884a',3,null,null,'informal','very bad',null,null,'خیلی بد',array['terrible']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The path was in a shocking state .","translation":"مسیر در حالت تکان دهنده ای بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000675849.mp3"},{"sentence":"I’ve got a shocking cold.","translation":"من یک سرماخوردگی تکان دهنده دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001589020.mp3"}]'::jsonb,2),
('cbc5fcf7-621b-5871-97b3-b1f242570028','8abd7b25-4a68-54c2-9906-da2a01aa415c',1,null,null,'spoken & written','the activity of going to shops and buying things',null,'window-shopping','خرید، خرید (بازار)؛ خرید (فرد)؛ خرید (سالی)','{}'::text[],'{}'::text[],array['go shopping She skipped lunch in order to go shopping.','do some/the/your shopping I thought you wanted to do some shopping.','Christmas shopping So you''ve done all your Christmas shopping, have you?','grocery shopping She even enjoys grocery shopping.','home shopping (= buying things at home, for example from a catalogue )','a shopping expedition/trip His shopping trip with Uncle Billy had been a thorough success.','a shopping spree (= when you buy a lot of things ) He admits to going on a shopping spree with someone else''s credit card.','a shopping list (= a list of what you need to buy, especially of food ) Always take a shopping list so you are not tempted to buy things you do not need.']::text[],'[{"sentence":"Late-night shopping is becoming very popular.","translation":"خرید در اواخر شب بسیار محبوب شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000676861.mp3"},{"sentence":"She’s gone on a shopping trip to New York.","translation":"او برای خرید به نیویورک رفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001601264.mp3"},{"sentence":"I went on a shopping spree (= went shopping and bought a lot of things ) at the weekend and spent far too much money.","translation":"آخر هفته به خرید رفتم (= رفتم خرید و چیزهای زیادی خریدم) و خیلی پول خرج کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001601271.mp3"},{"sentence":"I’ve got to do some last-minute shopping.","translation":"من باید در لحظه آخر خرید کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002092341.mp3"},{"sentence":"the busy Christmas shopping season","translation":"فصل شلوغ خرید کریسمس","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002092342.mp3"}]'::jsonb,5),
('ee0b575c-c01c-5507-b083-beb9a2ecf172','8abd7b25-4a68-54c2-9906-da2a01aa415c',2,null,null,'spoken & written',null,null,'do the shopping','خرید، خرید (بازار)؛ خرید (فرد)؛ خرید (سالی)','{}'::text[],'{}'::text[],array['go shopping She skipped lunch in order to go shopping.','do some/the/your shopping I thought you wanted to do some shopping.','Christmas shopping So you''ve done all your Christmas shopping, have you?','grocery shopping She even enjoys grocery shopping.','home shopping (= buying things at home, for example from a catalogue )','a shopping expedition/trip His shopping trip with Uncle Billy had been a thorough success.','a shopping spree (= when you buy a lot of things ) He admits to going on a shopping spree with someone else''s credit card.','a shopping list (= a list of what you need to buy, especially of food ) Always take a shopping list so you are not tempted to buy things you do not need.']::text[],'[]'::jsonb,0),
('c454ceaa-33b2-5b16-9bfc-86ccf2982732','8abd7b25-4a68-54c2-9906-da2a01aa415c',3,null,null,'spoken & written','the things that you have just bought from a shop',null,null,'چیزهایی که به تازگی از یک مغازه خریده اید','{}'::text[],'{}'::text[],array['go shopping She skipped lunch in order to go shopping.','do some/the/your shopping I thought you wanted to do some shopping.','Christmas shopping So you''ve done all your Christmas shopping, have you?','grocery shopping She even enjoys grocery shopping.','home shopping (= buying things at home, for example from a catalogue )','a shopping expedition/trip His shopping trip with Uncle Billy had been a thorough success.','a shopping spree (= when you buy a lot of things ) He admits to going on a shopping spree with someone else''s credit card.','a shopping list (= a list of what you need to buy, especially of food ) Always take a shopping list so you are not tempted to buy things you do not need.']::text[],'[{"sentence":"Can you help me carry the shopping, please?","translation":"آیا می توانید به من کمک کنید تا خرید را انجام دهم، لطفا؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001601280.mp3"}]'::jsonb,1),
('980c7619-10cd-5448-90ff-7fc02263b684','87e556cf-c557-5e76-9300-1ea0fee3d5d1',1,'body part','قسمت بدن','spoken & written','one of the two parts of the body at each side of the neck where the arm is connected','[ countable ]',null,'شانه؛ شانه (کمر)؛ شانه (جاده)','{}'::text[],'{}'::text[],array['shrug your shoulders (= raise them to show that you do not know or care about something ) Susan just shrugged her shoulders and said nothing.','hunch your shoulders (= raise your shoulders and bend them forwards slightly ) He hunched his shoulders against the rain.','look/glance over your shoulder (= look behind you ) He glanced over his shoulder and grinned at me.','somebody’s shoulders shake (= because they are crying or laughing ) His shoulders were shaking and tears of laughter were running down his face.','somebody’s shoulders slump/droop/sag (= move downwards because they are sad or tired ) ‘You ''re right, ’ he sighed, his shoulders drooping.','somebody’s shoulders heave (= move up and down because they are crying or breathing deeply ) She turned her back again, her shoulders heaving, her eyes blind with tears.','straighten/square your shoulders (= stand with your shoulders straight, in a determined way ) She squared her shoulders and knocked on the door.','broad/wide He was of medium height, with broad shoulders.','strong/powerful He had powerful shoulders and a thick neck.','massive/huge Dean shrugged his massive shoulders.','narrow/slim Her dark hair spilled over her narrow shoulders.','thin/bony shoulders She put her arm around the girl’s thin shoulders.']::text[],'[{"sentence":"She tapped the driver on the shoulder.","translation":"ضربه ای به شانه راننده زد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000678215.mp3"},{"sentence":"He put his arm around her shoulders.","translation":"دستش را دور شانه هایش انداخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600912.mp3"},{"sentence":"His shoulders were broad and powerful.","translation":"شانه هایش پهن و قدرتمند بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001454.mp3"}]'::jsonb,3),
