('e3bee925-0801-5be5-a02a-85d3cb3a271c','bfbc74cd-f84b-5047-86f6-c1237d4a346c',1,null,null,'spoken & written','used to mean a person, when you do not know or do not say who the person is',null,null,'کسی، فردی (ناشناس)؛ شخص (غیرمعلوم)',array['someone']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There’s somebody waiting to see you.","translation":"یک نفر منتظر دیدن شماست","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648479.mp3"},{"sentence":"Somebody’s car alarm kept me awake all night.","translation":"زنگ ماشین یک نفر مرا تمام شب بیدار نگه داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648480.mp3"},{"sentence":"We need somebody neutral to sort this out.","translation":"ما به یک نفر بی طرف نیاز داریم تا این موضوع را حل کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648483.mp3"},{"sentence":"If you can’t make it Friday, we can invite somebody else (= a different person ) .","translation":"اگر نمی‌توانید جمعه را به پایان برسانید، می‌توانیم شخص دیگری (= فرد دیگری) را دعوت کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633677.mp3"},{"sentence":"‘Who can we get to babysit?’ ‘I’ll call Suzie or somebody .’","translation":"\"چه کسی را می توانیم برای نگهداری از کودک بیاوریم؟\" \"من به سوزی یا کسی زنگ می زنم.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633682.mp3"}]'::jsonb,5),
