('fc3b960f-7dbe-511a-b319-52e0422dd4cc','1a9f1787-ef67-5ec9-87a3-0feab2e2d661',1,null,null,'spoken & written','more than a little but not very',null,null,'تا حدی، نسبتاً؛ کم‌وبیش','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The price is somewhat higher than I expected.","translation":"قیمت کمی بالاتر از حد انتظار من است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648791.mp3"},{"sentence":"Things have changed somewhat since then.","translation":"از آن زمان تا حدودی اوضاع تغییر کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633782.mp3"},{"sentence":"To say that I was surprised is somewhat of an understatement.","translation":"گفتن اینکه من شگفت زده شدم تا حدودی دست کم گرفته شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001780976.mp3"}]'::jsonb,3),
