('f45b3969-6704-58ed-965a-0a2d50d79e8e','f31c8cac-6f9c-5d32-983e-91e9673eecd3',1,null,null,'spoken & written','the act of spelling words correctly, or the ability to do this','[ uncountable ]',null,'املا، املای (کلمه)؛ املای (درست)؛ املای (کلمه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Her spelling has improved.","translation":"املای او بهتر شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000656780.mp3"},{"sentence":"an essay full of spelling mistakes","translation":"مقاله ای پر از اشتباهات املایی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001623785.mp3"}]'::jsonb,2),
