('020cea63-19f8-5cc0-bb9b-4ca9eb6b11b8','3f73b0bd-01ea-5f78-a4b1-21f5935e90d9',1,null,null,'spoken & written','if you feel or believe in something strongly, you are very sure and serious about it',null,null,'به‌شدت، به‌طور قوی؛ محکم (باور)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m strongly opposed to capital punishment.","translation":"من به شدت با مجازات اعدام مخالفم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001620891.mp3"},{"sentence":"We strongly believe that she is innocent.","translation":"ما قویاً معتقدیم که او بی گناه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001620895.mp3"},{"sentence":"I’m strongly in favour of marriage.","translation":"من به شدت طرفدار ازدواج هستم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001620896.mp3"}]'::jsonb,3),
('2c3c9605-3e5f-52f1-8aae-ed65cbb84040','3f73b0bd-01ea-5f78-a4b1-21f5935e90d9',2,null,null,'spoken & written','in a way that is meant to persuade someone to do something',null,null,'به نحوی که قصد دارد کسی را به انجام کاری متقاعد کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Before taking action, you are strongly recommended to consult an accountant.","translation":"قبل از اقدام، اکیداً توصیه می شود با یک حسابدار مشورت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001620902.mp3"}]'::jsonb,1),
('61cd2523-920c-5de5-a836-1ac0f027bc19','3f73b0bd-01ea-5f78-a4b1-21f5935e90d9',3,null,null,'spoken & written','in a way that is easy to notice',null,null,'به گونه ای که به راحتی قابل توجه است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The house smelt strongly of food.","translation":"خانه به شدت بوی غذا می داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001620906.mp3"}]'::jsonb,1),
('bb231f8a-b020-576e-8332-643b119f9071','09a68fbe-5bfc-528a-af72-9db7849d7365',1,null,null,'spoken & written','to try extremely hard to achieve something, even though it is very difficult',null,null,'تلاش کردن، سعی کردن (سخت)؛ دست‌وپا زدن (در)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s struggling to bring up a family alone.","translation":"او برای تشکیل خانواده به تنهایی تلاش می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582212.mp3"},{"sentence":"The airline is struggling with high costs.","translation":"این شرکت هواپیمایی با هزینه های بالا دست و پنجه نرم می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582215.mp3"},{"sentence":"Millions of people are struggling for survival.","translation":"میلیون ها نفر برای بقا تلاش می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000623260.mp3"},{"sentence":"Firms are struggling against a prolonged recession.","translation":"شرکت ها در برابر رکود طولانی مدت مبارزه می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582218.mp3"}]'::jsonb,4),
('57d257c3-9381-5712-8f10-60ac84b10c68','09a68fbe-5bfc-528a-af72-9db7849d7365',2,null,null,'spoken & written','to fight someone who is attacking you or holding you, especially so that you can escape',null,null,'برای مبارزه با کسی که به شما حمله می کند یا شما را نگه می دارد، به خصوص برای اینکه بتوانید فرار کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"James was hit in the mouth as he struggled with the burglars.","translation":"جیمز در حالی که با سارقان مبارزه می کرد به دهانش ضربه خورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582223.mp3"},{"sentence":"She struggled to free herself.","translation":"او تلاش کرد تا خود را آزاد کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582226.mp3"},{"sentence":"They struggled for possession of the gun.","translation":"آنها برای داشتن اسلحه مبارزه کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582231.mp3"}]'::jsonb,3),
('17f87273-02c5-5e06-a3a1-669cd196c306','09a68fbe-5bfc-528a-af72-9db7849d7365',3,null,null,'spoken & written','to move somewhere with great difficulty',null,null,'برای حرکت به جایی با سختی زیاد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Walkers were struggling up the dusty track.","translation":"واکرها به سختی از مسیر پر گرد و غبار بالا می رفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000623276.mp3"}]'::jsonb,1),
('ee38a1fe-7c25-5dcf-abb4-37d4fd5b1a26','09a68fbe-5bfc-528a-af72-9db7849d7365',4,null,null,'spoken & written','to be likely to fail , even though you are trying very hard',null,null,'به احتمال زیاد شکست می خورید، حتی اگر خیلی تلاش می کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The team has been struggling all season.","translation":"این تیم در تمام فصل با مشکل مواجه بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582234.mp3"}]'::jsonb,1),
('36ff6468-6825-5a69-bfe2-1868ca00d9dc','b4ccc951-ab16-57e0-b07e-ad9efff29014',1,null,null,'spoken & written','a long hard fight to get freedom , political rights etc',null,null,'کش و قوس، جدال (طولانی)؛ تقلای (فرد)؛ کشمکش (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a struggle for survival","translation":"مبارزه برای بقا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582239.mp3"},{"sentence":"a power struggle between forces favoring and opposing change","translation":"جنگ قدرت بین نیروهای طرفدار و مخالف تغییر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582240.mp3"}]'::jsonb,2),
('9d6656b4-cc26-5400-aa44-b47e24ee1f02','b4ccc951-ab16-57e0-b07e-ad9efff29014',2,null,null,'spoken & written','a long period of time in which you try to deal with a difficult problem',null,null,'یک دوره زمانی طولانی که در آن سعی می کنید با یک مشکل دشوار کنار بیایید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She spoke of her struggles with shyness.","translation":"او از مبارزات خود با کمرویی صحبت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582248.mp3"}]'::jsonb,1),
('395be9b7-be13-5ab9-bdc0-98a505582ba3','b4ccc951-ab16-57e0-b07e-ad9efff29014',3,null,null,'spoken & written','a fight between two people for something, or an attempt by one person to escape from the other',null,null,'دعوای دو نفر برای چیزی یا تلاش یک نفر برای فرار از دست دیگری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Police said there were no signs of a struggle.","translation":"پلیس گفت هیچ نشانه ای از درگیری وجود ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001582249.mp3"}]'::jsonb,1),
('9e561683-2bbb-507a-ad69-5e18ea79c7a1','b4ccc951-ab16-57e0-b07e-ad9efff29014',4,null,null,'spoken & written',null,null,'be a struggle (for somebody)','کش و قوس، جدال (طولانی)؛ تقلای (فرد)؛ کشمکش (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('688c7304-4bd3-5be4-ab62-f679a2b3083d','851d57e0-3291-5986-be05-847aa66be753',1,null,null,'spoken & written','quickly and unexpectedly','[ sentence adverb ]',null,'ناگهان، ناگهانی؛ ناگهانی (پیش آمده)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I suddenly realized that there was someone following me.","translation":"ناگهان متوجه شدم که یک نفر دنبالم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000628206.mp3"},{"sentence":"George died very suddenly.","translation":"جورج خیلی ناگهانی درگذشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000628207.mp3"},{"sentence":"Suddenly, the eagle opened its wings.","translation":"ناگهان عقاب بال هایش را باز کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001984413.mp3"}]'::jsonb,3),
('1e4ec59e-7c18-51e7-9bcf-e0fb080c5538','93ab4a21-451a-5eba-b0de-80f1a2304b85',1,null,null,'spoken & written','having the right qualities for a particular person, purpose , or situation',null,null,'مناسب، شایسته (برای)','{}'::text[],'{}'::text[],array['very/highly suitable ( also eminently suitable formal ) This exercise is very suitable for back pain sufferers.','particularly/especially suitable The resort is particularly suitable for families.','equally suitable I wanted a shoe that was equally suitable for both racing and training.','perfectly suitable (= completely suitable ) The programme is perfectly suitable for children of all ages.']::text[],'[{"sentence":"We are hoping to find a suitable school.","translation":"امیدواریم مدرسه مناسبی پیدا کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000632100.mp3"},{"sentence":"The house is not really suitable for a large family.","translation":"این خانه واقعا برای یک خانواده پرجمعیت مناسب نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000632103.mp3"},{"sentence":"a suitable place to rear young children","translation":"مکانی مناسب برای پرورش کودکان خردسال","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607727.mp3"},{"sentence":"These crayons are not suitable to use in very hot weather.","translation":"این مداد رنگی ها برای استفاده در هوای بسیار گرم مناسب نیستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000632106.mp3"},{"sentence":"We think this is the right school for our child.","translation":"ما فکر می کنیم این مدرسه مناسب برای فرزندمان است.","audio_url":null}]'::jsonb,5),
('afcbc1b6-09c1-57d9-a364-3b18f9fd7565','70f80041-43d5-57c9-b345-b464ff2c5921',1,'event','رویداد','spoken & written','an unexpected or unusual event','[ countable ]',null,'شگفتی، تعجب؛ غافلگیری (فرد)؛ شگفتی (حالت)','{}'::text[],'{}'::text[],array['be a surprise His decision to marry was a complete surprise.','come as a surprise (= be surprising ) The announcement came as a surprise to most people.','get/have a surprise We got a surprise when we got home and found him waiting for us.','give somebody a surprise She wanted to give him a surprise.','have a surprise for somebody (= be planning to give someone a surprise ) I think Jenny might have a surprise for you.','spring a surprise (on somebody) (= give someone a surprise ) The chairman sprang a surprise this week by announcing his intention to quit.','a big/great surprise The results were a big surprise.','a complete/total surprise The news came as a complete surprise.','a nice/pleasant/lovely surprise It’s a lovely surprise to see you.','an unpleasant/nasty surprise We don’t want any unpleasant surprises.','come as no surprise (= not be surprising ) It came as no surprise when Lester got the job.','be in for a surprise (= be going to have a surprise ) Compare our prices. You’ll be in for a pleasant surprise.','there’s a surprise in store (for somebody) (= something unexpected is going to happen ) There were plenty more surprises in store for him.','a surprise visit Environmental health inspectors made a surprise visit to the restaurant.','a surprise party His friends had planned a surprise party for him.','a surprise announcement In a surprise announcement the company said they were withdrawing their planning application.','a surprise victory She came to power in 1977, after a surprise victory in the general election.','a surprise attack Instead they launched a successful surprise attack on the castle.','a surprise move (= an unexpected action ) In a surprise move, the government lifted the ban on arms exports to the country.']::text[],'[{"sentence":"What a surprise to find you here!","translation":"چه شگفت انگیز است که شما را در اینجا پیدا کردم!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000602257.mp3"},{"sentence":"We had a big surprise when we found out the truth.","translation":"وقتی حقیقت را فهمیدیم شگفتی بزرگی داشتیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001565.mp3"}]'::jsonb,2),
('df1d30ae-97d2-537d-99e5-fddd203dffbc','70f80041-43d5-57c9-b345-b464ff2c5921',2,'feeling','احساس','spoken & written','the feeling you have when something unexpected or unusual happens','[ countable, uncountable ]',null,'احساسی که هنگام وقوع اتفاق غیرمنتظره یا غیرمعمولی دارید','{}'::text[],'{}'::text[],array['be a surprise His decision to marry was a complete surprise.','come as a surprise (= be surprising ) The announcement came as a surprise to most people.','get/have a surprise We got a surprise when we got home and found him waiting for us.','give somebody a surprise She wanted to give him a surprise.','have a surprise for somebody (= be planning to give someone a surprise ) I think Jenny might have a surprise for you.','spring a surprise (on somebody) (= give someone a surprise ) The chairman sprang a surprise this week by announcing his intention to quit.','a big/great surprise The results were a big surprise.','a complete/total surprise The news came as a complete surprise.','a nice/pleasant/lovely surprise It’s a lovely surprise to see you.','an unpleasant/nasty surprise We don’t want any unpleasant surprises.','come as no surprise (= not be surprising ) It came as no surprise when Lester got the job.','be in for a surprise (= be going to have a surprise ) Compare our prices. You’ll be in for a pleasant surprise.','there’s a surprise in store (for somebody) (= something unexpected is going to happen ) There were plenty more surprises in store for him.','a surprise visit Environmental health inspectors made a surprise visit to the restaurant.','a surprise party His friends had planned a surprise party for him.','a surprise announcement In a surprise announcement the company said they were withdrawing their planning application.','a surprise victory She came to power in 1977, after a surprise victory in the general election.','a surprise attack Instead they launched a successful surprise attack on the castle.','a surprise move (= an unexpected action ) In a surprise move, the government lifted the ban on arms exports to the country.']::text[],'[{"sentence":"The man had a look of surprise on his face.","translation":"مرد در چهره اش تعجب داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001616341.mp3"},{"sentence":"Bill looked at him in surprise.","translation":"بیل با تعجب به او نگاه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000602284.mp3"},{"sentence":"Much to his surprise, she gave him her phone number.","translation":"در کمال تعجب او شماره تلفن خود را به او داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000602288.mp3"},{"sentence":"To my surprise, the whole family was there.","translation":"در کمال تعجب، تمام خانواده آنجا بودند.","audio_url":null}]'::jsonb,4),
('1d24a3ff-48b3-5ba0-917b-014c30c0bc21','70f80041-43d5-57c9-b345-b464ff2c5921',3,null,null,'spoken & written',null,null,'take/catch somebody by surprise','شگفتی، تعجب؛ غافلگیری (فرد)؛ شگفتی (حالت)','{}'::text[],'{}'::text[],array['be a surprise His decision to marry was a complete surprise.','come as a surprise (= be surprising ) The announcement came as a surprise to most people.','get/have a surprise We got a surprise when we got home and found him waiting for us.','give somebody a surprise She wanted to give him a surprise.','have a surprise for somebody (= be planning to give someone a surprise ) I think Jenny might have a surprise for you.','spring a surprise (on somebody) (= give someone a surprise ) The chairman sprang a surprise this week by announcing his intention to quit.','a big/great surprise The results were a big surprise.','a complete/total surprise The news came as a complete surprise.','a nice/pleasant/lovely surprise It’s a lovely surprise to see you.','an unpleasant/nasty surprise We don’t want any unpleasant surprises.','come as no surprise (= not be surprising ) It came as no surprise when Lester got the job.','be in for a surprise (= be going to have a surprise ) Compare our prices. You’ll be in for a pleasant surprise.','there’s a surprise in store (for somebody) (= something unexpected is going to happen ) There were plenty more surprises in store for him.','a surprise visit Environmental health inspectors made a surprise visit to the restaurant.','a surprise party His friends had planned a surprise party for him.','a surprise announcement In a surprise announcement the company said they were withdrawing their planning application.','a surprise victory She came to power in 1977, after a surprise victory in the general election.','a surprise attack Instead they launched a successful surprise attack on the castle.','a surprise move (= an unexpected action ) In a surprise move, the government lifted the ban on arms exports to the country.']::te