('275e6178-1b05-5b27-8794-cd6c46c79efe','91ad78e9-28f4-592c-96c6-6b49033e5613',1,null,null,'spoken & written','someone who is together is confident , thinks clearly, and does things in a sensible organized way – used to show approval',null,null,'کسی که با هم هستند اعتماد به نفس دارد، به وضوح فکر می کند و کارها را به روشی معقول و منظم انجام می دهد - برای نشان دادن تایید استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Jane is such a together person.","translation":"جین چنین فردی با هم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000576493.mp3"}]'::jsonb,1),
('4d097dee-3d97-5e3a-9f68-fac5b73871ee','ffe19953-8bd7-5b65-9987-3517218a98e5',1,null,null,'spoken & written','on or during the day after today',null,null,'فردا، فردا (روز)؛ فردا (آینده)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Our class is going to London tomorrow.","translation":"کلاس ما فردا به لندن می رود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000957029.mp3"},{"sentence":"Terry’s new job starts a week tomorrow.","translation":"کار جدید تری از فردا یک هفته شروع می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000957036.mp3"},{"sentence":"We’re meeting tomorrow evening.","translation":"فردا عصر همدیگر را داریم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001603383.mp3"}]'::jsonb,3),
('356b99c1-d9d2-5cf8-8a54-4f3aaf8f0b47','170cb766-591a-5fdf-9902-27214f52676e',1,null,null,'spoken & written','the day after today',null,null,'پس از امروز','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’ll see you at tomorrow’s meeting.","translation":"من شما را در جلسه فردا می بینم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000577126.mp3"}]'::jsonb,1),
('8718e3d3-69df-540c-b924-9483a69f3eef','170cb766-591a-5fdf-9902-27214f52676e',2,null,null,'spoken & written','the future , especially the near future',null,null,'آینده، به ویژه آینده نزدیک','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The computers of tomorrow will be smaller and more powerful.","translation":"کامپیوترهای فردا کوچکتر و قدرتمندتر خواهند شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000577134.mp3"}]'::jsonb,1),
